  React.ComponentProps<typeof PreviewCardPrimitive.Portal>,
  'keepMounted'
>;

function PreviewCardPortal(props: PreviewCardPortalProps) {
  const { isOpen } = usePreviewCard();

  return (
    <AnimatePresence>
      {isOpen && (
        <PreviewCardPrimitive.Portal
          keepMounted
          data-slot="preview-card-portal"
          {...props}
        />
      )}
