    as = motion.div,
    transition = { duration: 0.2, ease: 'easeInOut' },
    ...rest
  } = props;

  return (
    <DialogBackdropPrimitive
      key="dialog-backdrop"
      data-slot="dialog-backdrop"
      as={as as React.ElementType}
      initial={{ opacity: 0, filter: 'blur(4px)', transition }}
