const DRAG_THRESHOLD = 3;

const SLIDER_TRANSITION: Transition = motionTokens.spring.slider;

const PRESSED_STRETCH = 19 / 16;

type SliderMotionItem = {
  snapshot: () => void;
  play: () => void;
  cancel: () => void;
};

type SliderMotionContext = {
  isPressing: boolean;
  register: (item: SliderMotionItem) => () => void;
  startPress: (event: React.PointerEvent) => void;
};

const [SliderMotionProvider, useSliderMotion] =
  getStrictContext<SliderMotionContext>('Slider.Root');

type PressState = { x: number; y: number; moved: boolean; pending: boolean };

function useSliderRootMotion({
  disabled,
  valuesKey,
}: {
  disabled?: boolean;
  valuesKey: string;
}) {
  const reduce = useShouldReduceMotion();
  const [isPressing, setIsPressing] = React.useState(false);
  const itemsRef = React.useRef(new Set<SliderMotionItem>());
  const pressRef = React.useRef<PressState | null>(null);
  const stopListeningRef = React.useRef<(() => void) | null>(null);

  const register = React.useCallback((item: SliderMotionItem) => {
    itemsRef.current.add(item);
    return () => {
      itemsRef.current.delete(item);
    };
  }, []);

  React.useEffect(() => () => stopListeningRef.current?.(), []);

  const startPress = (event: React.PointerEvent) => {
    if (disabled || event.button !== 0 || event.defaultPrevented) return;
    stopListeningRef.current?.();

    const press: PressState = {
      x: event.clientX,
      y: event.clientY,
      moved: false,
      pending: !reduce,
    };
    pressRef.current = press;
    if (press.pending) itemsRef.current.forEach((item) => item.snapshot());
    setIsPressing(true);

    const onMove = (moveEvent: PointerEvent) => {
      if (press.moved) return;
      const distance = Math.hypot(
        moveEvent.clientX - press.x,
        moveEvent.clientY - press.y,
      );
      if (distance <= DRAG_THRESHOLD) return;
      press.moved = true;
      press.pending = false;
      itemsRef.current.forEach((item) => item.cancel());
    };
    const onUp = () => {
      stopListening();
      if (pressRef.current === press) pressRef.current = null;
      setIsPressing(false);
    };
    const stopListening = () => {
      window.removeEventListener('pointermove', onMove);
      window.removeEventListener('pointerup', onUp);
      window.removeEventListener('pointercancel', onUp);
      stopListeningRef.current = null;
    };

    window.addEventListener('pointermove', onMove);
    window.addEventListener('pointerup', onUp);
    window.addEventListener('pointercancel', onUp);
    stopListeningRef.current = stopListening;
  };

  React.useLayoutEffect(() => {
    const press = pressRef.current;
    if (press?.pending) {
      press.pending = false;
      queueMicrotask(() => itemsRef.current.forEach((item) => item.play()));
    } else if (!press || press.moved) {
      itemsRef.current.forEach((item) => item.cancel());
    }
  }, [valuesKey]);

  return { isPressing, register, startPress };
}

type FlipStart = { tx: number; ty: number; sx: number; sy: number };

const IDENTITY: FlipStart = { tx: 0, ty: 0, sx: 1, sy: 1 };

function measureLayout(el: HTMLElement, base: string) {
  const transform = el.style.transform;
  el.style.transform = base || 'none';
  const rect = el.getBoundingClientRect();
  el.style.transform = transform;
  return rect;
}

function sameBox(a: DOMRect, b: DOMRect) {
  return (
    Math.abs(a.left - b.left) < 0.5 &&
    Math.abs(a.top - b.top) < 0.5 &&
    Math.abs(a.width - b.width) < 0.5 &&
    Math.abs(a.height - b.height) < 0.5
  );
}

const toTransform = (base: string, [tx, ty, sx, sy]: number[]) =>
  `${base ? `${base} ` : ''}translateX(${tx}px) translateY(${ty}px) scaleX(${sx}) scaleY(${sy})`;

function useSliderPartMotion(
  kind: 'thumb' | 'range',
  transition: Transition,
  base = '',
) {
  const { register } = useSliderMotion();
  const ref = React.useRef<HTMLElement | null>(null);
  const tx = useMotionValue(0);
  const ty = useMotionValue(0);
  const sx = useMotionValue(1);
  const sy = useMotionValue(1);

  const baseRef = React.useRef(base);
  const transitionRef = React.useRef(transition);
  React.useLayoutEffect(() => {
    baseRef.current = base;
    transitionRef.current = transition;
  });

  const transform = useTransform([tx, ty, sx, sy], (values) =>
    toTransform(baseRef.current, values as number[]),
  );

  React.useEffect(() => {
    let snapshot: { visual: DOMRect; layout: DOMRect } | null = null;
    let controls: AnimationPlaybackControls[] = [];

    const stop = () => {
      controls.forEach((c) => c.stop());
      controls = [];
    };
    const set = (start: FlipStart) => {
      tx.jump(start.tx);
      ty.jump(start.ty);
      sx.jump(start.sx);
      sy.jump(start.sy);
      if (ref.current) {
        ref.current.style.transform = toTransform(baseRef.current, [
          start.tx,
          start.ty,
          start.sx,
          start.sy,
        ]);
      }
    };

    return register({
      snapshot() {
        const el = ref.current;
        snapshot = el
          ? {
              visual: el.getBoundingClientRect(),
              layout: measureLayout(el, baseRef.current),
            }
          : null;
      },
      play() {
        const el = ref.current;
        const from = snapshot;
        snapshot = null;
        if (!el || !from) return;
        const layout = measureLayout(el, baseRef.current);
        if (sameBox(layout, from.layout)) return;

        stop();
        const visual = from.visual;
        if (kind === 'thumb') {
          set({
            tx:
              visual.left + visual.width / 2 - (layout.left + layout.width / 2),
            ty:
              visual.top + visual.height / 2 - (layout.top + layout.height / 2),
            sx: 1,
            sy: 1,
          });
        } else {
          if (layout.width < 1 || layout.height < 1) {
            set(IDENTITY);
            return;
          }
          set({
            tx: visual.left - layout.left,
            ty: visual.top - layout.top,
            sx: visual.width / layout.width,
            sy: visual.height / layout.height,
          });
        }
        const t = transitionRef.current;
        const rest = (size: number): Transition =>
          t.type === 'spring'
            ? { restDelta: 0.5 / size, restSpeed: 2 / size, ...t }
            : t;
        controls = [
          animate(tx, 0, t),
          animate(ty, 0, t),
          animate(sx, 1, rest(layout.width)),
          animate(sy, 1, rest(layout.height)),
        ];
      },
      cancel() {
        snapshot = null;
        const atRest =
          tx.get() === 0 && ty.get() === 0 && sx.get() === 1 && sy.get() === 1;
        if (controls.length === 0 && atRest) return;
        stop();
        set(IDENTITY);
      },
    });
  }, [kind, register, tx, ty, sx, sy]);

  return { ref, transform };
}

type Stretch = {
  size: MotionValue<number>;
  natural: number;
  axis: 'width' | 'height';
  stretched: boolean;
  controls: AnimationPlaybackControls | null;
};

function naturalSize(el: HTMLElement, axis: 'width' | 'height') {
  const inline = el.style[axis];
  el.style[axis] = '';
  const size = axis === 'width' ? el.offsetWidth : el.offsetHeight;
  el.style[axis] = inline;
  return size;
}

function useThumbStretch(
  ref: React.RefObject<HTMLElement | null>,
  pressed: boolean,
  transition: Transition,
) {
  const reduce = useShouldReduceMotion();
  const stretchRef = React.useRef<Stretch | null>(null);
  const transitionRef = React.useRef(transition);
  React.useLayoutEffect(() => {
    transitionRef.current = transition;
  });

  React.useLayoutEffect(() => {
    const el = ref.current;
    if (!el) return;
    let s = stretchRef.current;
    if (!s) {
      const stretch: Stretch = {
        size: motionValue(0),
        natural: 0,
        axis: 'width',
        stretched: false,
        controls: null,
      };
      stretch.size.on('change', (size) => {
        if (stretch.stretched) el.style[stretch.axis] = `${size}px`;
      });
      s = stretchRef.current = stretch;
    }
    const stretch = s;
    const press = pressed && !reduce;
    if (!press && !stretch.stretched) return;
    stretch.controls?.stop();
    if (press && !stretch.stretched) {
      const vertical =
        el.closest('[data-orientation]')?.getAttribute('data-orientation') ===
        'vertical';
      stretch.axis = vertical ? 'height' : 'width';
      stretch.natural = naturalSize(el, stretch.axis);
      stretch.stretched = true;
      stretch.size.jump(stretch.natural);
    }
    if (reduce) {
      stretch.stretched = false;
      el.style[stretch.axis] = '';
      return;
    }
    const target = press ? stretch.natural * PRESSED_STRETCH : stretch.natural;
    const controls = animate(stretch.size, target, transitionRef.current);
    stretch.controls = controls;
    void controls.then(() => {
      if (stretch.controls !== controls || press) return;
      stretch.controls = null;
      stretch.stretched = false;
      el.style[stretch.axis] = '';
    });
  }, [ref, pressed, reduce]);

  React.useEffect(
    () => () => {
      stretchRef.current?.controls?.stop();
    },
    [],
  );
}

function assignRef<T>(ref: React.Ref<T> | undefined, node: T | null) {
  if (typeof ref === 'function') ref(node);
  else if (ref) ref.current = node;
}

export {
  SLIDER_TRANSITION,
  SliderMotionProvider,
  useSliderMotion,
  useSliderRootMotion,
  useSliderPartMotion,
  useThumbStretch,
  assignRef,
};

'use client';

import * as React from 'react';
import type { Transition } from 'motion/react';

import {
  motionTokens,
  toCssTiming,
  useShouldReduceMotion,
  useTempoTransition,
} from '../utils/motion';
import { curveFrom, velocityOf, INSTANT, type Run } from './momentum';

type Box = { x: number; y: number; width: number; height: number };

type IndicatorSnapshot = Box & {
  version: number;
  item: Element;
  className: string;
  attributes: Record<string, string>;
};

const SKIPPED_ATTRIBUTE =
  /^data-(slot|testid|animate-ui-.*|hovered|pressed|focused|focus-visible|highlighted|rac|react-aria-.*|key|radix-.*|composite-.*)$/;

const NONE = (value: string) => !value || value === 'none';

function layoutSizeOf(element: HTMLElement) {
  const style = getComputedStyle(element);
  let width = parseFloat(style.width);
  let height = parseFloat(style.height);
  if (!Number.isFinite(width) || !Number.isFinite(height))
    return { width: element.offsetWidth, height: element.offsetHeight };
  if (style.boxSizing !== 'border-box') {
    const px = (value: string) => parseFloat(value) || 0;
    width +=
      px(style.paddingLeft) +
      px(style.paddingRight) +
      px(style.borderLeftWidth) +
      px(style.borderRightWidth);
    height +=
      px(style.paddingTop) +
      px(style.paddingBottom) +
      px(style.borderTopWidth) +
      px(style.borderBottomWidth);
  }
  return { width, height };
}

function containerScale(container: HTMLElement, rect: DOMRect) {
  const { width, height } = layoutSizeOf(container);
  return {
    x: width && Math.abs(rect.width - width) > 0.01 ? rect.width / width : 1,
    y:
      height && Math.abs(rect.height - height) > 0.01
        ? rect.height / height
        : 1,
  };
}

function lengthOf(value: string, size: number) {
  if (value.endsWith('%')) return (parseFloat(value) / 100) * size;
  if (value.endsWith('px') || /^-?[\d.]+$/.test(value))
    return parseFloat(value);
  return null;
}

function untransform(element: Element, box: Box): Box {
  const style = getComputedStyle(element);
  if (NONE(style.translate) && NONE(style.scale) && NONE(style.transform))
    return box;
  if (!NONE(style.rotate)) return box;
  let [a, d, e, f] = [1, 1, 0, 0];
  if (!NONE(style.transform)) {
    const matrix = style.transform.match(/^matrix\(([^)]+)\)$/);
    if (!matrix) return box;
    const [ma = 1, mb = 0, mc = 0, md = 1, me = 0, mf = 0] = matrix[1]!
      .split(',')
      .map(Number);
    if (Math.abs(mb) > 1e-6 || Math.abs(mc) > 1e-6) return box;
    [a, d, e, f] = [ma, md, me, mf];
  }
  const scale = NONE(style.scale) ? [] : style.scale.split(/\s+/).map(Number);
  const sx = scale[0] ?? 1;
  const sy = scale[1] ?? sx;
  const [kx, ky] = [sx * a, sy * d];
  if (!kx || !ky || ![kx, ky].every(Number.isFinite)) return box;
  const width = box.width / kx;
  const height = box.height / ky;
  const [tX = '0px', tY = '0px'] = NONE(style.translate)
    ? []
    : style.translate.split(/\s+(?![^(]*\))/);
  const tx = lengthOf(tX, width);
  const ty = lengthOf(tY, height);
  const [oX = '0px', oY = '0px'] = style.transformOrigin.split(/\s+/);
  const ox = lengthOf(oX, width);
  const oy = lengthOf(oY, height);
  if (tx === null || ty === null || ox === null || oy === null) return box;
  return {
    x: box.x - ox - tx - sx * (e - a * ox),
    y: box.y - oy - ty - sy * (f - d * oy),
    width,
    height,
  };
}

function boxIn(
  container: HTMLElement,
  element: Element,
  untransformed = false,
): Box {
  const containerRect = container.getBoundingClientRect();
  const rect = element.getBoundingClientRect();
  const scale = containerScale(container, containerRect);
  const box = {
    x:
      (rect.left - containerRect.left) / scale.x -
      container.clientLeft +
      container.scrollLeft,
    y:
      (rect.top - containerRect.top) / scale.y -
      container.clientTop +
      container.scrollTop,
    width: rect.width / scale.x,
    height: rect.height / scale.y,
  };
  return untransformed ? untransform(element, box) : box;
}

function isTransformed(container: HTMLElement) {
  const rect = container.getBoundingClientRect();
  const { width, height } = layoutSizeOf(container);
  return (
    Math.abs(rect.width - width) > 0.01 || Math.abs(rect.height - height) > 0.01
  );
}

const sameBox = (a: Box, b: Box) =>
  Math.abs(a.x - b.x) < 0.01 &&
  Math.abs(a.y - b.y) < 0.01 &&
  Math.abs(a.width - b.width) < 0.01 &&
  Math.abs(a.height - b.height) < 0.01;

type BoxOf = (item: HTMLElement, container: HTMLElement) => Element;

type SlidingIndicatorConfig = {
  findActive: (container: HTMLElement) => HTMLElement | null;
  items: string;
  attributes: string[];
  style: { href: string; css: string };
  slot: string;
  reducedMotion?: 'jump' | 'fade';
  untransformed?: boolean;
  zIndex?: number;
  fadeBackground?: boolean;
};

function readSnapshot(
  container: HTMLElement,
  previous: IndicatorSnapshot | null,
  {
    copy,
    boxOf,
    config,
  }: { copy: boolean; boxOf?: BoxOf; config: SlidingIndicatorConfig },
): IndicatorSnapshot | null {
  const item = config.findActive(container);
  if (!item) return null;

  const box = boxIn(
    container,
    boxOf?.(item, container) ?? item,
    config.untransformed,
  );
  const attributes: Record<string, string> = {};
  if (copy) {
    for (const { name, value } of item.attributes) {
      if (name.startsWith('data-') && !SKIPPED_ATTRIBUTE.test(name))
        attributes[name] = value;
    }
  }
  const className = copy ? (item.getAttribute('class') ?? '') : '';

  if (
    previous &&
    previous.item === item &&
    sameBox(previous, box) &&
    previous.className === className &&
    JSON.stringify(previous.attributes) === JSON.stringify(attributes)
  )
    return previous;

  return {
    version:
      previous && previous.item !== item
        ? previous.version + 1
        : (previous?.version ?? 0),
    item,
    ...box,
    className,
    attributes,
  };
}

const isInIndicator = (node: Node, slot: string) =>
  node instanceof Element && node.closest(`[data-slot="${slot}"]`) !== null;

type Slide = {
  animations: Animation[];
  run: Run;
  to: Box;
};

const isRunning = (animation: Animation | undefined) =>
  animation !== undefined &&
  animation.playState !== 'finished' &&
  animation.playState !== 'idle';

const timeOf = (animation: Animation | undefined) =>
  Number(animation?.currentTime) || 0;

function startNow(animation: Animation) {
  animation.startTime = performance.now();
  return animation;
}

function boxOfSlide({ animations, run, to }: Slide): Box {
  const left = 1 - run.curve.at(timeOf(animations[0]));
  const [x = 0, y = 0, width = 0, height = 0] = run.offset;
  return {
    x: to.x + x * left,
    y: to.y + y * left,
    width: to.width + width * left,
    height: to.height + height * left,
  };
}

function onNextFrame(callback: () => void) {
  const frame = requestAnimationFrame(callback);
  return () => cancelAnimationFrame(frame);
}

const SLIDING_ATTRIBUTE = 'data-animate-ui-sliding';
const LEAVING_ATTRIBUTE = 'data-animate-ui-leaving';

const placement = (
  box: Box,
  zIndex: number,
  transition = 'none',
): React.CSSProperties => ({
  position: 'absolute',
  left: box.x,
  top: box.y,
  right: 'auto',
  bottom: 'auto',
  width: box.width,
  height: box.height,
  margin: 0,
  boxSizing: 'border-box',
  zIndex,
  pointerEvents: 'none',
  transition,
});

type Crossfades = {
  copies: Map<HTMLElement, Animation>;
  fadeIn: Animation | null;
};

type SlidingIndicatorOptions = {
  enabled?: boolean;
  transition?: Transition;
  surface?: {
    className?: string;
    style?: React.CSSProperties;
    slot?: string;
  };
  boxOf?: BoxOf;
};

function stopCrossfades(crossfades: Crossfades) {
  for (const [copy, animation] of crossfades.copies) {
    animation.cancel();
    copy.remove();
  }
  crossfades.copies.clear();
  crossfades.fadeIn?.cancel();
  crossfades.fadeIn = null;
}

const INDICATOR_TRANSITION: Transition = motionTokens.spring.selection;

function useSlidingIndicator(
  container: HTMLElement | null,
  config: SlidingIndicatorConfig,
  { enabled = true, transition, surface, boxOf }: SlidingIndicatorOptions = {},
) {
  const [snapshot, setSnapshot] = React.useState<IndicatorSnapshot | null>(
    null,
  );
  const copy = !surface;
  const slot = surface?.slot ?? config.slot;

  const boxOfRef = React.useRef(boxOf);
  const configRef = React.useRef(config);
  React.useLayoutEffect(() => {
    boxOfRef.current = boxOf;
    configRef.current = config;
  });

  React.useLayoutEffect(() => {
    if (!container || !enabled) return;
    if (getComputedStyle(container).position === 'static')
      container.style.position = 'relative';
    container.style.isolation = 'isolate';

    let reread = 0;
    let rereads = 0;
    const update = () => {
      setSnapshot((previous) =>
        readSnapshot(container, previous, {
          copy,
          boxOf: boxOfRef.current,
          config: configRef.current,
        }),
      );
      if (!isTransformed(container)) {
        rereads = 0;
        return;
      }
      if (reread || ++rereads > 90) return;
      reread = requestAnimationFrame(() => {
        reread = 0;
        update();
      });
    };
    const resize = new ResizeObserver(update);
    const observeItems = () => {
      resize.observe(container);
      for (const item of container.querySelectorAll<HTMLElement>(
        configRef.current.items,
      )) {
        resize.observe(item);
        const box = boxOfRef.current?.(item, container);
        if (box && box !== item) resize.observe(box);
      }
    };
    const mutations = new MutationObserver((records) => {
      if (records.every((r) => isInIndicator(r.target, slot))) return;
      observeItems();
      update();
    });
    mutations.observe(container, {
      subtree: true,
      childList: true,
      characterData: true,
      attributes: true,
      attributeFilter: configRef.current.attributes,
    });
    container.addEventListener('scroll', update, {
      capture: true,
      passive: true,
    });
    observeItems();
    update();

    return () => {
      mutations.disconnect();
      resize.disconnect();
      container.removeEventListener('scroll', update, { capture: true });
      cancelAnimationFrame(reread);
    };
  }, [container, enabled, copy, slot]);

  const visible = container && enabled ? snapshot : null;

  const slideTransition = useTempoTransition(
    transition ?? INDICATOR_TRANSITION,
  );
  const fade = toCssTiming(useTempoTransition(motionTokens.transition.fade));
  const color = toCssTiming(useTempoTransition(motionTokens.transition.color));
  const reduce = useShouldReduceMotion();
  const latestRef = React.useRef({
    slideTransition,
    fade,
    reduce,
    copy,
    slot,
    surface,
  });
  React.useLayoutEffect(() => {
    latestRef.current = { slideTransition, fade, reduce, copy, slot, surface };
  });

  const indicatorRef = React.useRef<HTMLSpanElement | null>(null);
  const slideRef = React.useRef<Slide | null>(null);
  const crossfadesRef = React.useRef<Crossfades>({
    copies: new Map(),
    fadeIn: null,
  });
  const restRef = React.useRef<{
    version: number;
    box: Box;
    className: string;
    attributes: Record<string, string>;
  } | null>(null);
  const paintedRef = React.useRef(false);
  React.useLayoutEffect(
    () => onNextFrame(() => (paintedRef.current = true)),
    [],
  );

  React.useLayoutEffect(() => {
    const element = indicatorRef.current;
    const slide = slideRef.current;
    const stop = () => {
      slide?.animations.forEach((animation) => animation.cancel());
      slideRef.current = null;
      element?.removeAttribute(SLIDING_ATTRIBUTE);
    };
    if (!element || !visible) {
      stop();
      stopCrossfades(crossfadesRef.current);
      restRef.current = null;
      return;
    }

    const to: Box = {
      x: visible.x,
      y: visible.y,
      width: visible.width,
      height: visible.height,
    };
    const rest = restRef.current;
    restRef.current = {
      version: visible.version,
      box: to,
      className: visible.className,
      attributes: visible.attributes,
    };
    const moving = slide !== null && isRunning(slide.animations[0]);
    if (
      !rest ||
      !paintedRef.current ||
      (visible.version === rest.version && !moving)
    ) {
      stop();
      return;
    }

    const from = moving ? boxOfSlide(slide) : rest.box;
    const velocity = moving
      ? velocityOf(slide.run, timeOf(slide.animations[0]))
      : [0, 0, 0, 0];
    const startTime = moving
      ? Math.max(
          Number(document.timeline.currentTime),
          Number(slide.animations[0]!.startTime),
        ) || performance.now()
      : performance.now();
    stop();
    const offset = [
      from.x - to.x,
      from.y - to.y,
      from.width - to.width,
      from.height - to.height,
    ];
    if (offset.every((value) => Math.abs(value) < 0.5)) return;
    if (typeof element.animate !== 'function') return;

    const { slideTransition, fade, reduce, copy, slot, surface } =
      latestRef.current;

    if (reduce && configRef.current.reducedMotion === 'fade') {
      const crossfades = crossfadesRef.current;
      if (fade.duration <= 0) {
        stopCrossfades(crossfades);
        return;
      }
      const opacity = isRunning(crossfades.fadeIn ?? undefined)
        ? Number(getComputedStyle(element).opacity)
        : 1;
      crossfades.fadeIn?.cancel();
      const copied = document.createElement('span');
      copied.setAttribute('aria-hidden', 'true');
      for (const [name, value] of Object.entries(rest.attributes))
        copied.setAttribute(name, value);
      copied.setAttribute('data-slot', slot);
      copied.setAttribute(LEAVING_ATTRIBUTE, '');
      if (copy) copied.className = rest.className;
      else if (surface?.className) copied.className = surface.className;
      Object.assign(copied.style, surface?.style);
      copied.style.cssText += `;position:absolute;left:${from.x}px;top:${from.y}px;right:auto;bottom:auto;width:${from.width}px;height:${from.height}px;margin:0;box-sizing:border-box;z-index:${configRef.current.zIndex ?? -1};pointer-events:none;transition:none`;
      element.before(copied);
      const out = startNow(
        copied.animate([{ opacity }, { opacity: 0 }], {
          duration: fade.duration * opacity,
          easing: fade.easing,
          fill: 'both',
        }),
      );
      crossfades.copies.set(copied, out);
      out.onfinish = () => {
        copied.remove();
        crossfades.copies.delete(copied);
      };
      crossfades.fadeIn = startNow(
        element.animate([{ opacity: 0 }, { opacity: 1 }], {
          duration: fade.duration,
          easing: fade.easing,
          fill: 'backwards',
        }),
      );
      return;
    }

    const curve = reduce
      ? INSTANT
      : curveFrom(slideTransition, offset, velocity);
    if (curve.duration <= 0) return;
    const timing: KeyframeAnimationOptions = {
      duration: curve.duration,
      easing: curve.easing,
      fill: 'backwards',
    };
    const own = getComputedStyle(element).translate;
    const [ownX = 0, ownY = 0] = NONE(own)
      ? []
      : own
          .split(/\s+/)
          .map((part) => (part.endsWith('px') ? parseFloat(part) : NaN));
    const replace = Number.isFinite(ownX) && Number.isFinite(ownY);
    const animations = [
      element.animate(
        replace
          ? [
              { translate: `${offset[0]! + ownX}px ${offset[1]! + ownY}px` },
              { translate: `${ownX}px ${ownY}px` },
            ]
          : [
              { translate: `${offset[0]}px ${offset[1]}px` },
              { translate: '0px 0px' },
            ],
        { ...timing, composite: replace ? 'replace' : 'add' },
      ),
    ];
    if (Math.abs(offset[2]!) >= 0.5 || Math.abs(offset[3]!) >= 0.5)
      animations.push(
        element.animate(
          [
            { width: `${from.width}px`, height: `${from.height}px` },
            { width: `${to.width}px`, height: `${to.height}px` },
          ],
          timing,
        ),
      );
    for (const animation of animations) animation.startTime = startTime;
    const started: Slide = { animations, run: { offset, curve }, to };
    slideRef.current = started;
    element.setAttribute(SLIDING_ATTRIBUTE, '');
    void animations[0]!.finished.then(
      () => {
        if (slideRef.current === started)
          element.removeAttribute(SLIDING_ATTRIBUTE);
      },
      () => {},
    );
  }, [visible]);

  React.useEffect(
    () => () => {
      slideRef.current?.animations.forEach((animation) => animation.cancel());
      stopCrossfades(crossfadesRef.current);
    },
    [],
  );

  const ready = Boolean(visible && copy);
  const [settled, setSettled] = React.useState(false);
  const [wasReady, setWasReady] = React.useState(ready);
  if (ready !== wasReady) {
    setWasReady(ready);
    if (!ready) setSettled(false);
  }
  React.useLayoutEffect(() => {
    if (!ready || settled) return;
    return onNextFrame(() => setSettled(true));
  }, [ready, settled]);

  const indicator = visible ? (
    <>
      {copy && (
        <style href={config.style.href} precedence="animate-ui">
          {config.style.css}
        </style>
      )}
      <span
        ref={indicatorRef}
        aria-hidden
        {...visible.attributes}
        data-slot={slot}
        className={copy ? visible.className : surface?.className}
        style={{
          ...surface?.style,
          ...placement(
            visible,
            config.zIndex ?? -1,
            config.fadeBackground
              ? `background-color ${color.duration}ms ${color.easing}`
              : 'none',
          ),
        }}
      />
    </>
  ) : null;

  return {
    indicator,
    ready,
    settling: ready && !settled,
  };
}

export {
  useSlidingIndicator,
  layoutSizeOf,
  SLIDING_ATTRIBUTE,
  LEAVING_ATTRIBUTE,
  onNextFrame,
  startNow,
  isRunning,
  type SlidingIndicatorConfig,
  type SlidingIndicatorOptions,
};

'use client';

import * as React from 'react';
import { flushSync } from 'react-dom';
import type { Transition } from 'motion/react';

import {
  motionTokens,
  toCssTiming,
  useShouldReduceMotion,
  useTempoTransition,
  type CssTiming,
} from '../utils/motion';
import { curveFrom } from './momentum';
import {
  isRunning,
  onNextFrame,
  startNow,
  useSlidingIndicator,
  type SlidingIndicatorConfig,
  type SlidingIndicatorOptions,
  layoutSizeOf,
} from './sliding-indicator';

const TAB_ATTRIBUTE = 'data-animate-ui-tab';
const READY_ATTRIBUTE = 'data-animate-ui-indicator';
const SETTLING_ATTRIBUTE = 'data-animate-ui-indicator-settling';
const COLOR_DURATION_VAR = '--animate-ui-tab-color-duration';
const COLOR_EASING_VAR = '--animate-ui-tab-color-easing';

const SURFACE_CSS = [
  `[${READY_ATTRIBUTE}] [${TAB_ATTRIBUTE}][aria-selected="true"]{background-color:transparent;background-image:none}`,
  `[${READY_ATTRIBUTE}] [${TAB_ATTRIBUTE}][aria-selected="true"]:not(:focus-visible){border-color:transparent;box-shadow:none}`,
  `[${READY_ATTRIBUTE}] [${TAB_ATTRIBUTE}][aria-selected="true"]::after{opacity:0}`,
  `[${READY_ATTRIBUTE}] [${TAB_ATTRIBUTE}]{transition-property:color,background-color,border-color,outline-color,text-decoration-color,fill,stroke;transition-duration:var(${COLOR_DURATION_VAR},.2s);transition-timing-function:var(${COLOR_EASING_VAR},ease)}`,
  `[${SETTLING_ATTRIBUTE}] [${TAB_ATTRIBUTE}][aria-selected="true"]{transition:none}`,
].join('');

function findActiveTab(list: HTMLElement) {
  for (const tab of list.querySelectorAll(`[${TAB_ATTRIBUTE}]`)) {
    if (
      tab.getAttribute('aria-selected') === 'true' &&
      tab.closest('[role="tablist"]') === list
    )
      return tab as HTMLElement;
  }
  return null;
}

const TABS_INDICATOR: SlidingIndicatorConfig = {
  findActive: findActiveTab,
  items: `[${TAB_ATTRIBUTE}]`,
  attributes: [
    'aria-selected',
    'class',
    'data-state',
    'data-active',
    'data-selected',
    'data-orientation',
    'data-disabled',
  ],
  style: { href: 'animate-ui-tabs-indicator', css: SURFACE_CSS },
  slot: 'tabs-indicator',
};

type TabsIndicatorOptions = SlidingIndicatorOptions;

function useTabsIndicator(
  list: HTMLElement | null,
  options: TabsIndicatorOptions = {},
) {
  const { enabled = true, surface } = options;
  const copy = !surface;
  const { indicator, ready, settling } = useSlidingIndicator(
    list,
    TABS_INDICATOR,
    options,
  );

  const color = toCssTiming(useTempoTransition(motionTokens.transition.color));
  React.useLayoutEffect(() => {
    if (!list || !enabled || !copy) return;
    list.style.setProperty(COLOR_DURATION_VAR, `${color.duration}ms`);
    list.style.setProperty(COLOR_EASING_VAR, color.easing);
  }, [list, enabled, copy, color.duration, color.easing]);

  return {
    indicator,
    listProps: {
      [READY_ATTRIBUTE]: ready ? '' : undefined,
      [SETTLING_ATTRIBUTE]: settling ? '' : undefined,
    } as Record<string, string | undefined>,
  };
}

const HOLD_PROPERTY = '--animate-ui-tab-leaving';

type PanelStage = {
  current: object | null;
  shown: boolean;
  height: Extent | undefined;
  frame: { look: string; extent: Extent } | null;
  last: HTMLElement | null;
  panels: Map<object, { element: HTMLElement; selected: boolean }>;
  waiting: Set<() => void>;
  painted: boolean;
};

const stages = new WeakMap<Element, PanelStage>();

function stageOf(holder: Element) {
  let stage = stages.get(holder);
  if (!stage) {
    const created: PanelStage = {
      current: null,
      shown: false,
      height: undefined,
      frame: null,
      last: null,
      panels: new Map(),
      waiting: new Set(),
      painted: false,
    };
    onNextFrame(() => (created.painted = true));
    stages.set(holder, created);
    stage = created;
  }
  return stage;
}

function release(stage: PanelStage, token: object) {
  if (stage.current !== token) return;
  stage.current = null;
  for (const go of [...stage.waiting]) go();
}

const TRANSPARENT = /^transparent$|[,/]\s*0(?:\.0*)?\s*\)$/;
const SIDES = ['Top', 'Right', 'Bottom', 'Left'] as const;

function paintsBox(style: CSSStyleDeclaration) {
  return (
    SIDES.some(
      (side) =>
        parseFloat(style[`border${side}Width`]) > 0 &&
        style[`border${side}Style`] !== 'none' &&
        !TRANSPARENT.test(style[`border${side}Color`]),
    ) ||
    !TRANSPARENT.test(style.backgroundColor) ||
    style.backgroundImage !== 'none' ||
    style.boxShadow !== 'none'
  );
}

const hasText = (element: Element) =>
  Array.from(element.childNodes).some(
    (node) => node.nodeType === Node.TEXT_NODE && node.textContent?.trim(),
  );

function frameOf(panel: HTMLElement): HTMLElement | null {
  let element: Element = panel;
  for (;;) {
    if (!(element instanceof HTMLElement)) return null;
    if (paintsBox(getComputedStyle(element)))
      return hasText(element) ? null : element;
    const [child] = element.children;
    if (element.children.length !== 1 || !child || hasText(element))
      return null;
    element = child;
  }
}

const LOOK = [
  ...SIDES.flatMap((side) => [
    `border-${side.toLowerCase()}-width`,
    `border-${side.toLowerCase()}-style`,
    `border-${side.toLowerCase()}-color`,
  ]),
  'border-top-left-radius',
  'border-top-right-radius',
  'border-bottom-right-radius',
  'border-bottom-left-radius',
  'background-color',
  'background-image',
  'box-shadow',
];

function lookOf(frame: HTMLElement) {
  const style = getComputedStyle(frame);
  return LOOK.map((property) => style.getPropertyValue(property)).join('|');
}

type PanelAnimations = {
  fades: Map<Element, Animation>;
  targets: Element[];
  frame: HTMLElement | null;
  leaving: boolean;
  hold?: Animation;
  height?: Animation;
  follow?: { disconnect(): void };
};

const panelAnimations = new WeakMap<Element, PanelAnimations>();

function animationsOf(panel: Element) {
  let animations = panelAnimations.get(panel);
  if (!animations) {
    animations = { fades: new Map(), targets: [], frame: null, leaving: false };
    panelAnimations.set(panel, animations);
  }
  return animations;
}

function cancelAll(panel: Element) {
  const animations = panelAnimations.get(panel);
  if (!animations) return;
  for (const fade of animations.fades.values()) fade.cancel();
  animations.hold?.cancel();
  animations.height?.cancel();
  animations.follow?.disconnect();
  panelAnimations.delete(panel);
}

type Way = [number, number];

function wayOf(holder: Element, from: Element | null, to: Element | null) {
  if (!from?.isConnected || !to?.isConnected || from === to) return null;
  const later =
    from.compareDocumentPosition(to) & Node.DOCUMENT_POSITION_FOLLOWING
      ? 1
      : -1;
  let list: Element | null = null;
  for (let around: Element | null = holder; around && !list;)
    [list, around] = [
      around.querySelector('[role="tablist"]'),
      around.parentElement,
    ];
  const vertical =
    list?.getAttribute('aria-orientation') === 'vertical' ||
    list?.getAttribute('data-orientation') === 'vertical';
  if (vertical) return [0, later] as Way;
  const rtl = getComputedStyle(list ?? holder).direction === 'rtl';
  return [rtl ? -later : later, 0] as Way;
}

function shownNow(element: Element, blur: boolean, move: boolean): Keyframe {
  const style = getComputedStyle(element);
  const shown: Keyframe = { opacity: style.opacity };
  if (blur) shown.filter = style.filter === 'none' ? 'blur(0px)' : style.filter;
  if (move)
    shown.translate = style.translate === 'none' ? '0px 0px' : style.translate;
  return shown;
}

function gone(blur: boolean, way: Way | null): Keyframe {
  const hidden: Keyframe = { opacity: 0 };
  if (blur) hidden.filter = motionTokens.blur.panel;
  if (way) {
    const [x, y] = way.map((side) => side * motionTokens.shift.tabs);
    hidden.translate = `${x}px ${y}px`;
  }
  return hidden;
}

const POSITIONED = ['absolute', 'fixed'];

function anchorsOutside(target: Element) {
  if (getComputedStyle(target).position !== 'static') return false;
  const stack = [target];
  while (stack.length) {
    const element = stack.pop()!;
    for (const pseudo of ['::before', '::after'])
      if (POSITIONED.includes(getComputedStyle(element, pseudo).position))
        return true;
    for (const child of element.children) {
      const position = getComputedStyle(child).position;
      if (POSITIONED.includes(position)) return true;
      if (position === 'static') stack.push(child);
    }
  }
  return false;
}

function effectsOf(target: Element, timings: PanelTimings) {
  const plain = anchorsOutside(target);
  return { blur: timings.blur && !plain, move: timings.shift && !plain };
}

type PanelTimings = {
  in: CssTiming;
  out: CssTiming;
  height: CssTiming;
  follow: Transition;
  blur: boolean;
  glide: boolean;
  shift: boolean;
};

const targetsOf = (panel: HTMLElement, frame: HTMLElement | null) =>
  frame ? Array.from(frame.children) : [panel];

function fade(
  panel: HTMLElement,
  targets: Element[],
  frame: HTMLElement | null,
  keyframes: (target: Element) => Keyframe[],
  options: KeyframeAnimationOptions,
  leaving: boolean,
) {
  const animations = animationsOf(panel);
  const frames = targets.map(keyframes);
  targets.forEach((target, i) => {
    animations.fades.get(target)?.cancel();
    animations.fades.set(target, startNow(target.animate(frames[i]!, options)));
  });
  animations.targets = targets;
  animations.frame = frame;
  animations.leaving = leaving;
}

function fadeIn(
  panel: HTMLElement,
  targets: Element[],
  frame: HTMLElement | null,
  timings: PanelTimings,
  from: { way: Way | null } | null,
) {
  const animations = animationsOf(panel);
  animations.hold?.cancel();
  animations.hold = undefined;
  fade(
    panel,
    targets,
    frame,
    (target) => {
      const { blur, move } = effectsOf(target, timings);
      const start = from
        ? gone(blur, move ? from.way : null)
        : shownNow(target, blur, move);
      return [{ ...start, offset: 0 }];
    },
    {
      duration: timings.in.duration,
      easing: timings.in.easing,
      fill: 'backwards',
    },
    false,
  );
}

function fadeOut(
  panel: HTMLElement,
  targets: Element[],
  frame: HTMLElement | null,
  timings: PanelTimings,
  way: Way | null,
) {
  fade(
    panel,
    targets,
    frame,
    (target) => {
      const { blur, move } = effectsOf(target, timings);
      const away = move && way ? ([-way[0], -way[1]] as Way) : null;
      return [shownNow(target, blur, move), gone(blur, away)];
    },
    {
      duration: timings.out.duration,
      easing: timings.out.easing,
      fill: 'both',
    },
    true,
  );
}

const collapse = (a: number, b: number) =>
  Math.max(a, b, 0) + Math.min(a, b, 0);

function marginBelow(element: HTMLElement) {
  const style = getComputedStyle(element);
  const own = parseFloat(style.marginBottom) || 0;
  if (
    parseFloat(style.paddingBottom) > 0 ||
    parseFloat(style.borderBottomWidth) > 0
  )
    return own;
  const inline = element.getAttribute('style');
  const height = element.getBoundingClientRect().height;
  element.style.setProperty('transition', 'none', 'important');
  element.style.setProperty('padding-bottom', '1px', 'important');
  const one = element.getBoundingClientRect().height;
  element.style.setProperty('padding-bottom', '2px', 'important');
  const two = element.getBoundingClientRect().height;
  element.style.removeProperty('padding-bottom');
  void getComputedStyle(element).paddingBottom;
  if (inline === null) element.removeAttribute('style');
  else element.setAttribute('style', inline);
  if (Math.abs(two - one - 1) > 0.25) return own;
  return collapse(own, one - 1 - height);
}

type Extent = { height: number; margin: number };

function heightOf(element: HTMLElement) {
  const drawn = element.getBoundingClientRect().height;
  const layout = layoutSizeOf(element).height;
  return Math.abs(drawn - layout) < 0.01 ? drawn : layout;
}

const extentOf = (element: HTMLElement): Extent => ({
  height: heightOf(element),
  margin: marginBelow(element),
});

function glideHeight(
  panel: HTMLElement,
  target: HTMLElement,
  from: Extent,
  timing: CssTiming,
  follow: Transition,
) {
  const animations = animationsOf(panel);
  animations.height?.cancel();
  animations.height = undefined;
  animations.follow?.disconnect();
  animations.follow = undefined;
  const to = extentOf(target);
  if (!(to.height > 0)) return;
  const delay = (timing as CssTiming & { delay?: number }).delay ?? 0;
  const style = getComputedStyle(target);
  const own = parseFloat(style.marginBottom) || 0;
  const inset =
    style.boxSizing === 'border-box'
      ? 0
      : parseFloat(style.paddingTop) +
        parseFloat(style.paddingBottom) +
        parseFloat(style.borderTopWidth) +
        parseFloat(style.borderBottomWidth);
  const clip =
    style.overflowY === 'visible' ? { overflowY: ['clip', 'clip'] } : {};
  const run = (start: Extent, end: Extent, options: CssTiming) => {
    const sizes = [`${start.height - inset}px`, `${end.height - inset}px`];
    const margin =
      Math.abs(start.margin - own) > 0.5 || Math.abs(end.margin - own) > 0.5
        ? { marginBottom: [`${start.margin}px`, `${end.margin}px`] }
        : {};
    const animation = startNow(
      target.animate(
        { minHeight: sizes, maxHeight: sizes, ...margin, ...clip },
        { ...options, fill: 'backwards' },
      ),
    );
    animations.height = animation;
    return animation;
  };
  const same = (a: Extent, b: Extent) =>
    Math.abs(a.height - b.height) <= 0.5 &&
    Math.abs(a.margin - b.margin) <= 0.5;
  let end = to;
  let glide: Animation | null = same(from, to) ? null : run(from, to, timing);
  let waiting = delay > 0 ? glide : null;
  let rested = -Infinity;

  const check = () => {
    if (animations.height !== (glide ?? undefined)) return watch.disconnect();
    if (glide && glide === waiting && Number(glide.currentTime ?? 0) < 0) {
      const started = glide.startTime;
      glide.cancel();
      const natural = extentOf(target);
      if (!same(natural, end)) end = natural;
      glide = run(from, end, timing);
      glide.startTime = started;
      waiting = glide;
      return;
    }
    let now = end;
    let velocity = 0;
    let elapsed = 0;
    const running = !!glide && glide.playState !== 'finished';
    if (glide && running) {
      elapsed = Number(glide.currentTime ?? 0);
      now = {
        height: heightOf(target),
        margin: parseFloat(getComputedStyle(target).marginBottom) || 0,
      };
      const step = Math.min(elapsed, 8);
      glide.currentTime = elapsed - step;
      velocity = step > 0 ? (now.height - heightOf(target)) / step : 0;
      glide.cancel();
    }
    const natural = extentOf(target);
    if (same(natural, end)) {
      if (glide && running) {
        glide.play();
        glide.currentTime = elapsed;
      }
      return;
    }
    const time = performance.now();
    if (time - rested < 50) {
      animations.height = undefined;
      return watch.disconnect();
    }
    if (!running) rested = time;
    end = natural;
    const curve = curveFrom(follow, [now.height - natural.height], [velocity]);
    glide = run(now, natural, {
      duration: curve.duration,
      easing: curve.easing,
    });
  };
  const resize = new ResizeObserver(check);
  const mutation = new MutationObserver((records) => {
    for (const record of records)
      if (record.target === target)
        for (const node of record.addedNodes)
          if (node instanceof Element) resize.observe(node);
    check();
  });
  for (const child of target.children) resize.observe(child);
  mutation.observe(target, {
    childList: true,
    characterData: true,
    subtree: true,
  });
  const timer = setTimeout(
    () => watch.disconnect(),
    delay + timing.duration + toCssTiming(follow).duration,
  );
  const watch = {
    disconnect() {
      clearTimeout(timer);
      resize.disconnect();
      mutation.disconnect();
    },
  };
  animations.follow = watch;
}

function isGliding(panel: HTMLElement) {
  const height = panelAnimations.get(panel)?.height;
  return height !== undefined && isRunning(height);
}

function stopGlide(panel: HTMLElement) {
  const animations = panelAnimations.get(panel);
  if (!animations) return;
  animations.height?.cancel();
  animations.height = undefined;
  animations.follow?.disconnect();
  animations.follow = undefined;
}

const nextOf = (stage: PanelStage, token: object) =>
  [...stage.panels].find(
    ([other, entry]) => other !== token && entry.selected,
  )?.[1].element ?? null;

function leavingFrame(panel: HTMLElement, next: HTMLElement | null) {
  const animations = panelAnimations.get(panel);
  if (
    animations &&
    !animations.frame &&
    [...animations.fades.values()].some(isRunning)
  )
    return null;
  const frame = frameOf(panel);
  if (!frame) return null;
  const nextFrame = next ? frameOf(next) : null;
  return nextFrame && lookOf(nextFrame) === lookOf(frame) ? frame : null;
}

const isDisplayed = (element: HTMLElement) =>
  element.getClientRects().length > 0;

type PanelMotionOptions = {
  transition?: Transition;
  exitTransition?: Transition;
  heightTransition?: Transition;
};

function usePanelMotion(
  selected: boolean,
  { transition, exitTransition, heightTransition }: PanelMotionOptions = {},
) {
  const ref = React.useRef<HTMLElement | null>(null);
  const [token] = React.useState(() => ({}));
  const [exit, setExit] = React.useState<'open' | 'leaving' | 'closed'>(
    selected ? 'open' : 'closed',
  );
  const [waiting, setWaiting] = React.useState(false);

  if (selected && exit !== 'open') setExit('open');
  if (!selected && exit === 'open') setExit(waiting ? 'closed' : 'leaving');
  if (!selected && waiting) setWaiting(false);

  const reduce = useShouldReduceMotion();
  const enter = useTempoTransition(
    transition ?? motionTokens.transition.panelIn,
  );
  const leave = useTempoTransition(
    exitTransition ?? motionTokens.transition.panelOut,
  );
  const height = useTempoTransition(
    (transition as { height?: Transition } | undefined)?.height ??
      heightTransition ??
      transition ??
      motionTokens.transition.panelHeight,
  );
  const quickFade = useTempoTransition(motionTokens.transition.fade);
  const follow = useTempoTransition(motionTokens.spring.morph);
  const timings: PanelTimings = {
    in: toCssTiming(reduce ? quickFade : enter),
    out: toCssTiming(leave),
    height: toCssTiming(height),
    follow,
    blur: true,
    glide: !reduce,
    shift: !reduce,
  };
  const timingsRef = React.useRef(timings);
  React.useLayoutEffect(() => {
    timingsRef.current = timings;
  });
  const stageRef = React.useRef<PanelStage | null>(null);

  React.useLayoutEffect(() => {
    const element = ref.current;
    const holder = element?.parentElement;
    if (!element || !holder) return;
    const stage = stageOf(holder);
    stage.panels.set(token, { element, selected });
    return () => {
      stage.panels.delete(token);
    };
  });

  React.useLayoutEffect(() => {
    const element = ref.current;
    const holder = element?.parentElement;
    if (!selected || !element || !holder) return;
    const stage = stageOf(holder);
    stageRef.current = stage;

    if (waiting) {
      const go = () => setWaiting(false);
      if (!stage.current) go();
      else stage.waiting.add(go);
      return () => {
        stage.waiting.delete(go);
      };
    }

    if (stage.current && stage.current !== token) {
      setWaiting(true);
      return;
    }

    const timings = timingsRef.current;
    if (stage.current === token) {
      const own = panelAnimations.get(element);
      if (own?.leaving) fadeIn(element, own.targets, own.frame, timings, null);
      return;
    }

    stage.current = token;
    const way = wayOf(holder, stage.last, element);
    stage.last = element;
    const comesIn = stage.shown && stage.painted;
    stage.shown = true;
    const left = stage.frame;
    stage.frame = null;
    if (!comesIn || typeof element.animate !== 'function') return;
    const candidate = left ? frameOf(element) : null;
    const frame =
      left && candidate && lookOf(candidate) === left.look ? candidate : null;
    fadeIn(element, targetsOf(element, frame), frame, timings, { way });
    if (!timings.glide) return;
    if (frame && left)
      glideHeight(element, frame, left.extent, timings.height, timings.follow);
    else if (stage.height !== undefined)
      glideHeight(
        element,
        element,
        stage.height,
        timings.height,
        timings.follow,
      );
  }, [selected, waiting, token]);

  React.useLayoutEffect(() => {
    const element = ref.current;
    if (exit !== 'leaving') return;
    const stage = stageRef.current;
    let cancelled = false;
    const goes = () => {
      setExit('closed');
      if (stage) release(stage, token);
    };
    if (
      !element ||
      !stage ||
      stage.current !== token ||
      !stage.painted ||
      !isDisplayed(element) ||
      typeof element.animate !== 'function'
    ) {
      if (element) cancelAll(element);
      if (stage?.current === token) {
        stage.height = undefined;
        stage.frame = null;
      }
      goes();
      return;
    }

    const timings = timingsRef.current;
    const animations = animationsOf(element);
    animations.hold?.cancel();
    const hold = startNow(
      element.animate(
        { [HOLD_PROPERTY]: ['1', '1'] },
        { duration: timings.out.duration },
      ),
    );
    animations.hold = hold;
    queueMicrotask(() => {
      if (cancelled) return;
      const next = nextOf(stage, token);
      const frame = leavingFrame(element, next);
      const way = element.parentElement
        ? wayOf(element.parentElement, element, next)
        : null;
      fadeOut(element, targetsOf(element, frame), frame, timings, way);
    });
    hold.finished.then(
      () => {
        if (cancelled) return;
        const frame = panelAnimations.get(element)?.frame ?? null;
        stage.height = extentOf(element);
        stage.frame = frame
          ? { look: lookOf(frame), extent: extentOf(frame) }
          : null;
        // eslint-disable-next-line @eslint-react/dom-no-flush-sync
        flushSync(goes);
        cancelAll(element);
      },
      () => {},
    );
    return () => {
      cancelled = true;
    };
  }, [exit, token]);

  React.useLayoutEffect(
    () => () => {
      const stage = stageRef.current;
      if (stage) release(stage, token);
      if (ref.current) cancelAll(ref.current);
    },
    [token],
  );

  return {
    ref,
    waiting: selected && waiting,
    leaving: exit === 'leaving',
  };
}

