  return (
    <RootProvider
      value={{
        value,
        keepMounted: props.keepMounted,
        hiddenUntilFound: props.hiddenUntilFound,
      }}
    >
      <ReducedMotionConfig>
        <AccordionPrimitive.Root<Value>
          {...props}
          value={value}
          onValueChange={handleValueChange}
        />
      </ReducedMotionConfig>
    </RootProvider>
  );
}

