  return (
    <OpenProvider value={{ open }}>
      <ReducedMotionConfig>
        <CollapsiblePrimitive.Root
          {...props}
          open={open}
          onOpenChange={handleOpenChange}
        />
      </ReducedMotionConfig>
    </OpenProvider>
  );
