  return (
    <CustomIndicatorContext value={setCustomIndicator}>
      <TabsPrimitive.List
        {...props}
        {...listProps}
        ref={(node: HTMLDivElement | null) => {
          setList(node);
          if (typeof ref === 'function') return ref(node);
          if (ref) ref.current = node;
        }}
      >
        {indicator}
        {children}
      </TabsPrimitive.List>
    </CustomIndicatorContext>
