const SidebarContext = React.createContext<SidebarContextProps | null>(null);

const AnimateOnHoverContext = React.createContext(true);

function useSidebar() {
  const context = React.use(SidebarContext);
  if (!context) {
    throw new Error('useSidebar must be used within a SidebarProvider.');
  }
  return context;
}

const MOBILE_QUERY = `(max-width: ${MOBILE_BREAKPOINT - 1}px)`;

function subscribeMobile(onChange: () => void) {
  const mql = window.matchMedia(MOBILE_QUERY);
  mql.addEventListener('change', onChange);
  return () => mql.removeEventListener('change', onChange);
}

function useIsMobile() {
  return React.useSyncExternalStore(
    subscribeMobile,
    () => window.matchMedia(MOBILE_QUERY).matches,
    () => false,
  );
}

type ProviderProps = React.ComponentProps<'div'> & {
  defaultOpen?: boolean;
  open?: boolean;
  onOpenChange?: (open: boolean) => void;
  animateOnHover?: boolean;
};

function Provider({
  defaultOpen = true,
  open: openProp,
  onOpenChange,
  animateOnHover = true,
  style,
  children,
  ...props
}: ProviderProps) {
  const isMobile = useIsMobile();
  const [openMobile, setOpenMobile] = React.useState(false);

  const [uncontrolledOpen, setUncontrolledOpen] = React.useState(defaultOpen);
  const open = openProp ?? uncontrolledOpen;
  const setOpen = React.useCallback(
    (value: boolean | ((value: boolean) => boolean)) => {
      const openState = typeof value === 'function' ? value(open) : value;
      if (openProp === undefined) setUncontrolledOpen(openState);
      onOpenChange?.(openState);

      document.cookie = `${SIDEBAR_COOKIE_NAME}=${openState}; path=/; max-age=${SIDEBAR_COOKIE_MAX_AGE}`;
    },
    [onOpenChange, open, openProp],
  );

  const toggleSidebar = React.useCallback(() => {
    return isMobile ? setOpenMobile((open) => !open) : setOpen((open) => !open);
  }, [isMobile, setOpen]);

  React.useEffect(() => {
    const handleKeyDown = (event: KeyboardEvent) => {
      if (
        event.key === SIDEBAR_KEYBOARD_SHORTCUT &&
        (event.metaKey || event.ctrlKey) &&
        !(event.target as HTMLElement | null)?.closest?.(
          'input, textarea, select, [contenteditable]:not([contenteditable="false"])',
        )
      ) {
        event.preventDefault();
        toggleSidebar();
      }
    };

    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [toggleSidebar]);

  const state = open ? 'expanded' : 'collapsed';

  const contextValue = React.useMemo<SidebarContextProps>(
    () => ({
      state,
      open,
      setOpen,
      isMobile,
      openMobile,
      setOpenMobile,
      toggleSidebar,
    }),
    [state, open, setOpen, isMobile, openMobile, toggleSidebar],
  );

  const color = toCssTiming(useTempoTransition(COLOR_TRANSITION));
  const reduce = useShouldReduceMotion();
  const collapse = toCssTiming(useTempoTransition(COLLAPSE_TRANSITION));

  return (
    <SidebarContext value={contextValue}>
      <AnimateOnHoverContext value={animateOnHover}>
        <style href={SIDEBAR_STYLE.href} precedence="animate-ui">
          {SIDEBAR_STYLE.css}
        </style>
        <div
          {...props}
          style={
            {
              '--animate-ui-sidebar-color-duration': `${color.duration}ms`,
              '--animate-ui-sidebar-color-easing': color.easing,
              '--animate-ui-sidebar-duration': `${reduce ? 0 : collapse.duration}ms`,
              '--animate-ui-sidebar-easing': collapse.easing,
              ...style,
            } as React.CSSProperties
          }
        >
          {children}
        </div>
      </AnimateOnHoverContext>
    </SidebarContext>
  );
}

function useCssTransition(
  transition: Transition,
  properties: string,
): React.CSSProperties {
  const reduce = useShouldReduceMotion();
  const { duration, easing } = toCssTiming(useTempoTransition(transition));
  return {
    transitionProperty: properties,
    transitionDuration: `${reduce ? 0 : duration}ms`,
    transitionTimingFunction: easing,
    transitionDelay: '0ms',
  };
}

type GapProps = React.ComponentProps<'div'> & {
  transition?: Transition;
};

function Gap({ transition = COLLAPSE_TRANSITION, style, ...props }: GapProps) {
  const timing = useCssTransition(transition, 'width');
  return <div {...props} style={{ ...timing, ...style }} />;
}

type ContainerProps = React.ComponentProps<'div'> & {
  transition?: Transition;
};

function Container({
  transition = COLLAPSE_TRANSITION,
  style,
  ...props
}: ContainerProps) {
  const timing = useCssTransition(transition, 'left, right, width');
  return <div {...props} style={{ ...timing, ...style }} />;
}

const ITEMS = '[data-sidebar="menu-button"], [data-sidebar="menu-sub-button"]';
const DISABLED = ':disabled, [aria-disabled="true"], [data-disabled]';
const SURFACE = '[data-slot="trigger-highlight"]';

const roots = new WeakSet<Element>();

type Item = {
  node: HTMLElement;
  host: HTMLElement;
  disabled: boolean;
  key: number;
};

const keys = new WeakMap<HTMLElement, number>();
let nextKey = 0;
function keyOf(node: HTMLElement) {
  let key = keys.get(node);
  if (key === undefined) keys.set(node, (key = nextKey++));
  return key;
}

function closestRoot(node: HTMLElement) {
  for (let el = node.parentElement; el; el = el.parentElement)
    if (roots.has(el)) return el;
  return null;
}

const own = (root: HTMLElement, selector: string) =>
  [...root.querySelectorAll<HTMLElement>(selector)].filter(
    (node) => closestRoot(node) === root,
  );

const sameItems = (a: readonly Item[], b: readonly Item[]) =>
  a.length === b.length &&
  a.every(
    (item, i) =>
      item.node === b[i]!.node &&
      item.host === b[i]!.host &&
      item.disabled === b[i]!.disabled,
  );

const onlySurfaces = (record: MutationRecord) =>
  record.type === 'childList' &&
  [...record.addedNodes, ...record.removedNodes].every(
    (node) => node instanceof Element && node.matches(SURFACE),
  );

function useContentChanges(root: HTMLElement | null, onChange: () => void) {
  const onChangeRef = React.useRef(onChange);
  React.useLayoutEffect(() => {
    onChangeRef.current = onChange;
  });
  React.useLayoutEffect(() => {
    if (!root) return;
    onChangeRef.current();
    const observer = new MutationObserver((records) => {
      if (!records.every(onlySurfaces)) onChangeRef.current();
    });
    observer.observe(root, {
      childList: true,
      subtree: true,
      attributes: true,
      attributeFilter: [
        'data-sidebar',
        'disabled',
        'aria-disabled',
        'data-disabled',
      ],
    });
    return () => observer.disconnect();
  }, [root]);
}

const NO_ITEMS: readonly Item[] = [];

function useItems(root: HTMLElement | null) {
  const [items, setItems] = React.useState<readonly Item[]>([]);
  useContentChanges(root, () => {
    const found: Item[] = [];
    for (const node of own(root!, ITEMS)) {
      const host = node.parentElement;
      if (!host) continue;
      found.push({
        node,
        host,
        disabled: node.matches(DISABLED),
        key: keyOf(node),
      });
    }
    setItems((current) => (sameItems(current, found) ? current : found));
  });
  return root ? items : NO_ITEMS;
}

type CollapseMotionProps = {
  root: HTMLElement | null;
  state: string | undefined;
  timings: CollapseTimings;
};

class CollapseMotion extends React.Component<CollapseMotionProps> {
  getSnapshotBeforeUpdate(previous: CollapseMotionProps) {
    const { root, state } = this.props;
    if (!root || previous.state === state || previous.state === undefined)
      return null;
    return snapshotCollapse(root);
  }

  componentDidUpdate(
    _: CollapseMotionProps,
    __: unknown,
    snapshot: CollapseSnapshot | null,
  ) {
    const { root, timings } = this.props;
    if (root && snapshot) runCollapse(root, snapshot, timings);
  }

  componentWillUnmount() {
    if (this.props.root) stopCollapse(this.props.root);
  }

  render() {
    return null;
  }
}

function ItemSurface({ node, host, disabled }: Omit<Item, 'key'>) {
  const { ref, highlight } = useTriggerHighlight(disabled, { beside: true });
  React.useLayoutEffect(() => ref(node), [ref, node]);
  return highlight ? createPortal(highlight, host) : null;
}

type HighlightProps = React.ComponentProps<'div'> & {
  animateOnHover?: boolean;
};

function Highlight({
  animateOnHover,
  ref,
  style,
  children,
  ...props
}: HighlightProps) {
  const inherited = React.use(AnimateOnHoverContext);
  const sidebar = React.use(SidebarContext);
  const enabled = animateOnHover ?? inherited;
  const [root, setRoot] = React.useState<HTMLDivElement | null>(null);
  const setRootRef = React.useCallback((node: HTMLDivElement | null) => {
    if (node) roots.add(node);
    setRoot(node);
  }, []);
  const mergedRef = React.useMemo(
    () => mergeRefs(ref, setRootRef),
    [ref, setRootRef],
  );
  const items = useItems(enabled ? root : null);

  const reduce = useShouldReduceMotion();
  const collapse = toCssTiming(useTempoTransition(COLLAPSE_TRANSITION));
  const label = toCssTiming(useTempoTransition(LABEL_TRANSITION));
  const duration = reduce ? 0 : collapse.duration;
  const timings = React.useMemo<CollapseTimings>(
    () => ({
      duration,
      easing: collapse.easing,
      labelDuration: label.duration,
      labelEasing: label.easing,
      blur: motionTokens.blur.icon,
      reduce,
    }),
    [duration, collapse.easing, label.duration, label.easing, reduce],
  );

  return (
    <div
      {...props}
      ref={mergedRef}
      style={enabled ? { isolation: 'isolate', ...style } : style}
    >
      <TriggerHighlightScope>
        {children}
        {items.map(({ key, ...item }) => (
          <ItemSurface key={key} {...item} />
        ))}
      </TriggerHighlightScope>
      <CollapseMotion root={root} state={sidebar?.state} timings={timings} />
    </div>
  );
}

type TriggerIconProps = Omit<React.ComponentProps<'span'>, 'children'> & {
  open: React.ReactNode;
  closed: React.ReactNode;
  transition?: Transition;
};

function TriggerIcon({ open, closed, ...props }: TriggerIconProps) {
  const { state, isMobile, openMobile } = useSidebar();
  const isOpen = isMobile ? openMobile : state === 'expanded';
  return (
    <IconSwap swapKey={isOpen ? 'open' : 'closed'} {...props}>
      {isOpen ? open : closed}
    </IconSwap>
  );
}

export {
  Provider,
  Gap,
  Container,
  Highlight,
  TriggerIcon,
  useSidebar,
  type ProviderProps,
  type GapProps,
  type ContainerProps,
  type HighlightProps,
  type TriggerIconProps,
  type SidebarContextProps,
};

'use client';

import * as React from 'react';
import { motion, isMotionComponent, type HTMLMotionProps } from 'motion/react';

type AnyProps = Record<string, unknown>;

type DOMMotionProps<T extends HTMLElement = HTMLElement> = Omit<
  HTMLMotionProps<keyof HTMLElementTagNameMap>,
  'ref'
> & { ref?: React.Ref<T> };

type WithAsChild<Base extends object> =
  | (Base & { asChild: true; children: React.ReactElement })
  | (Base & { asChild?: false | undefined });

type SlotProps<T extends HTMLElement = HTMLElement> = {
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  children?: any;
} & DOMMotionProps<T>;

function mergeRefs<T>(
  ...refs: (React.Ref<T> | undefined)[]
): React.RefCallback<T> {
  return (node) => {
    refs.forEach((ref) => {
      if (!ref) return;
      if (typeof ref === 'function') {
        ref(node);
      } else {
        (ref as React.RefObject<T | null>).current = node;
      }
    });
  };
}

function mergeProps<T extends HTMLElement>(
  childProps: AnyProps,
  slotProps: DOMMotionProps<T>,
): AnyProps {
  const merged: AnyProps = { ...childProps, ...slotProps };

  for (const key in slotProps) {
    const slotHandler = slotProps[key as keyof typeof slotProps];
    const childHandler = childProps[key];
    if (
      /^on[A-Z]/.test(key) &&
      typeof slotHandler === 'function' &&
      typeof childHandler === 'function'
    ) {
      merged[key] = (...args: unknown[]) => {
        childHandler(...args);
        slotHandler(...args);
      };
    }
  }

  if (childProps.className || slotProps.className) {
    merged.className = [childProps.className, slotProps.className]
      .filter(Boolean)
      .join(' ');
  }

  if (childProps.style || slotProps.style) {
    merged.style = {
      ...(childProps.style as React.CSSProperties),
      ...(slotProps.style as React.CSSProperties),
    };
  }

  return merged;
}

function Slot<T extends HTMLElement = HTMLElement>({
  children,
  ref,
  ...props
}: SlotProps<T>) {
  const child = React.isValidElement(children) ? children : null;
  const type = child?.type;
  const isAlreadyMotion =
    typeof type === 'object' && type !== null && isMotionComponent(type);

  const Base = React.useMemo(
    () =>
      type === undefined
        ? null
        : isAlreadyMotion
          ? (type as React.ElementType)
          : motion.create(type as React.ElementType),
    [isAlreadyMotion, type],
  );

  if (!child || !Base) return null;

  const { ref: childRef, ...childProps } = child.props as AnyProps;

  const mergedProps = mergeProps(childProps, props);

  return (
    <Base {...mergedProps} ref={mergeRefs(childRef as React.Ref<T>, ref)} />
  );
}

export {
  Slot,
  type SlotProps,
  type WithAsChild,
  type DOMMotionProps,
  type AnyProps,
};

'use client';

import * as React from 'react';
import {
  motion,
  useMotionValue,
  useSpring as useMotionSpring,
  type SpringOptions,
  type HTMLMotionProps,
  type MotionValue,
} from 'motion/react';

import { ReducedMotionConfig, useShouldReduceMotion } from '../../utils/motion';
import { getStrictContext } from '../../utils/strict-context';
import { Slot, type WithAsChild } from '../slot';
import { useMotionValueState } from './use-motion-value-state';

type SpringPathConfig = {
  coilCount?: number;
  amplitudeMin?: number;
  amplitudeMax?: number;
  curveRatioMin?: number;
  curveRatioMax?: number;
  bezierOffset?: number;
};

function generateSpringPath(
  x1: number,
  y1: number,
  x2: number,
  y2: number,
  pathConfig: SpringPathConfig = {},
) {
  const {
    coilCount = 8,
    amplitudeMin = 8,
    amplitudeMax = 20,
    curveRatioMin = 0.5,
    curveRatioMax = 1,
    bezierOffset = 8,
  } = pathConfig;

  const dx = x2 - x1;
  const dy = y2 - y1;
  const dist = Math.sqrt(dx * dx + dy * dy);
  if (dist < 2) return `M${x1},${y1}`;
  const d = dist / coilCount;
  const h = Math.max(0.8, 1 - (dist - 40) / 200);
  const amplitude = Math.max(
    amplitudeMin,
    Math.min(amplitudeMax, amplitudeMax * h),
  );
  const curveRatio =
    dist <= 40
      ? curveRatioMax
      : dist <= 120
        ? curveRatioMax - ((dist - 40) / 80) * (curveRatioMax - curveRatioMin)
        : curveRatioMin;
  const ux = dx / dist,
    uy = dy / dist;
  const perpX = -uy,
    perpY = ux;

  const path: string[] = [];
  for (let i = 0; i < coilCount; i++) {
    const sx = x1 + ux * (i * d);
    const sy = y1 + uy * (i * d);
    const ex = x1 + ux * ((i + 1) * d);
    const ey = y1 + uy * ((i + 1) * d);

    const mx = x1 + ux * ((i + 0.5) * d) + perpX * amplitude;
    const my = y1 + uy * ((i + 0.5) * d) + perpY * amplitude;

    const c1x = sx + d * curveRatio * ux;
    const c1y = sy + d * curveRatio * uy;
    const c2x = mx + ux * bezierOffset;
    const c2y = my + uy * bezierOffset;
    const c3x = mx - ux * bezierOffset;
    const c3y = my - uy * bezierOffset;
    const c4x = ex - d * curveRatio * ux;
    const c4y = ey - d * curveRatio * uy;

    if (i === 0) path.push(`M${sx},${sy}`);
    else path.push(`L${sx},${sy}`);
    path.push(`C${c1x},${c1y} ${c2x},${c2y} ${mx},${my}`);
    path.push(`C${c3x},${c3y} ${c4x},${c4y} ${ex},${ey}`);
  }
  return path.join(' ');
}

type SpringContextType = {
  childRef: React.RefObject<HTMLDivElement | null>;
  springX: MotionValue<number>;
  springY: MotionValue<number>;
  x: MotionValue<number>;
  y: MotionValue<number>;
  isDragging: boolean;
  setIsDragging: (isDragging: boolean) => void;
  path: string;
};

const [LocalSpringProvider, useSpring] =
  getStrictContext<SpringContextType>('SpringContext');

type SpringProviderProps = {
  children: React.ReactNode;
  pathConfig?: SpringPathConfig;
  transition?: SpringOptions;
};

function SpringProvider({
  transition = { stiffness: 200, damping: 16 },
  pathConfig = {},
  children,
}: SpringProviderProps) {
  const x = useMotionValue(0);
  const y = useMotionValue(0);

  const springX = useMotionSpring(x, transition);
  const springY = useMotionSpring(y, transition);

  const sx = useMotionValueState(springX);
  const sy = useMotionValueState(springY);

  const childRef = React.useRef<HTMLDivElement>(null);

  const [center, setCenter] = React.useState({ x: 0, y: 0 });
  const [isDragging, setIsDragging] = React.useState(false);

  React.useLayoutEffect(() => {
    function update() {
      if (childRef.current) {
        const rect = childRef.current.getBoundingClientRect();
        setCenter({
          x: rect.left + rect.width / 2,
          y: rect.top + rect.height / 2,
        });
      }
    }

    update();

    window.addEventListener('resize', update);
    window.addEventListener('scroll', update, true);

    return () => {
      window.removeEventListener('resize', update);
      window.removeEventListener('scroll', update, true);
    };
  }, []);

  React.useEffect(() => {
    if (!isDragging) return;
    const previous = document.body.style.cursor;
    document.body.style.cursor = 'grabbing';
    return () => {
      document.body.style.cursor = previous;
    };
  }, [isDragging]);

  const path = generateSpringPath(
    center.x,
    center.y,
    center.x + sx,
    center.y + sy,
    pathConfig,
  );

  return (
    <LocalSpringProvider
      value={{
        springX,
        springY,
        x,
        y,
        isDragging,
        setIsDragging,
        childRef,
        path,
      }}
    >
      <ReducedMotionConfig>{children}</ReducedMotionConfig>
    </LocalSpringProvider>
  );
}

type SpringProps = React.SVGProps<SVGSVGElement>;

function Spring({ style, ...props }: SpringProps) {
  const { path } = useSpring();

  return (
    <svg
      width="100vw"
      height="100vh"
      style={{
        position: 'fixed',
        inset: 0,
        pointerEvents: 'none',
        ...style,
      }}
      {...props}
    >
      <path
        d={path}
        strokeLinecap="round"
        strokeLinejoin="round"
        stroke="currentColor"
        strokeWidth={2}
        fill="none"
      />
    </svg>
  );
}

type SpringElementProps = WithAsChild<
  Omit<HTMLMotionProps<'div'>, 'children'> & {
    children: React.ReactElement;
  }
>;

function SpringElement({
  ref,
  asChild = false,
  style,
  ...props
}: SpringElementProps) {
  const { childRef, isDragging, setIsDragging, springX, springY, x, y } =
    useSpring();

  React.useImperativeHandle(ref, () => childRef.current as HTMLDivElement);
  const reduce = useShouldReduceMotion();

  const Component = asChild ? Slot : motion.div;

  return (
    <Component
      ref={childRef}
      style={{
        cursor: isDragging ? 'grabbing' : 'grab',
        x: springX,
        y: springY,
        ...style,
      }}
      drag
      dragMomentum={false}
      onDragStart={() => {
        setIsDragging(true);
      }}
      onDrag={(_, info) => {
        x.set(info.offset.x);
        y.set(info.offset.y);
      }}
      onDragEnd={() => {
        x.set(0);
        y.set(0);
        if (reduce) {
          springX.jump(0);
          springY.jump(0);
        }
        setIsDragging(false);
      }}
      {...props}
    />
  );
}

export {
  SpringProvider,
  Spring,
  SpringElement,
  useSpring,
  type SpringProviderProps,
  type SpringProps,
  type SpringElementProps,
  type SpringPathConfig,
  type SpringContextType,
};

import * as React from 'react';
import { type MotionValue } from 'motion/react';

function useMotionValueState(motionValue: MotionValue): number {
  return React.useSyncExternalStore(
    (callback) => {
      const unsub = motionValue.on('change', callback);
      return unsub;
    },
    () => motionValue.get(),
    () => motionValue.get(),
  );
}

export { useMotionValueState };

'use client';

import * as React from 'react';
import { motion, type Transition, type HTMLMotionProps } from 'motion/react';

import {
  motionTokens,
  ReducedMotionConfig,
  useShouldReduceMotion,
  useTempoTransition,
} from '../../utils/motion';
import {
  Highlight,
  HighlightItem,
  type HighlightItemProps,
  type HighlightProps,
} from '../effects/highlight';
import { getStrictContext } from '../../utils/strict-context';
import { Slot, type WithAsChild } from '../slot';
import { layoutHeight } from '../../internal/screen-scale';

type TabsOrientation = 'horizontal' | 'vertical';

const HIGHLIGHT_TRANSITION: Transition = motionTokens.spring.selection;
const CONTENTS_TRANSITION: Transition = motionTokens.spring.slide;
const CONTENT_TRANSITION: Transition = motionTokens.spring.selection;

const INSTANT: Transition = { duration: 0 };

type TabsContextType = {
  activeValue: string;
  handleValueChange: (value: string) => void;
  registerTrigger: (value: string, node: HTMLElement | null) => void;
  orientation: TabsOrientation;
  getTriggerId: (value: string) => string;
  getContentId: (value: string) => string;
  getTriggerValue: (node: HTMLElement) => string | undefined;
  registerId: (
    kind: 'trigger' | 'content',
    value: string,
    id: string | undefined,
  ) => void;
};

const [TabsProvider, useTabs] =
  getStrictContext<TabsContextType>('TabsContext');

type BaseTabsProps = React.ComponentProps<'div'> & {
  children: React.ReactNode;
  orientation?: TabsOrientation;
};

type UnControlledTabsProps = BaseTabsProps & {
  defaultValue?: string;
  value?: never;
  onValueChange?: never;
};

type ControlledTabsProps = BaseTabsProps & {
  value: string;
  onValueChange?: (value: string) => void;
  defaultValue?: never;
};

type TabsProps = UnControlledTabsProps | ControlledTabsProps;

function Tabs({
  defaultValue,
  value,
  onValueChange,
  orientation = 'horizontal',
  children,
  ...props
}: TabsProps) {
  const baseId = React.useId();
  const [activeValue, setActiveValue] = React.useState<string | undefined>(
    defaultValue,
  );
  const triggersRef = React.useRef(new Map<string, HTMLElement>());
  const initialSet = React.useRef(false);
  const isControlled = value !== undefined;

  React.useEffect(() => {
    if (
      !isControlled &&
      activeValue === undefined &&
      triggersRef.current.size > 0 &&
      !initialSet.current
    ) {
      const firstTab = triggersRef.current.keys().next().value as
        string | undefined;
      if (firstTab !== undefined) {
        setActiveValue(firstTab);
        initialSet.current = true;
      }
    }
  }, [activeValue, isControlled]);

  const registerTrigger = React.useCallback(
    (val: string, node: HTMLElement | null) => {
      if (node) {
        triggersRef.current.set(val, node);
        if (!isControlled && activeValue === undefined && !initialSet.current) {
          setActiveValue(val);
          initialSet.current = true;
        }
      } else {
        triggersRef.current.delete(val);
      }
    },
    [activeValue, isControlled],
  );

  const handleValueChange = React.useCallback(
    (val: string) => {
      if (!isControlled) setActiveValue(val);
      else onValueChange?.(val);
    },
    [isControlled, onValueChange],
  );

  const [customIds, setCustomIds] = React.useState<
    Record<string, { trigger?: string; content?: string }>
  >({});
  const registerId = React.useCallback(
    (kind: 'trigger' | 'content', val: string, id: string | undefined) => {
      setCustomIds((prev) => {
        if (prev[val]?.[kind] === id) return prev;
        return { ...prev, [val]: { ...prev[val], [kind]: id } };
      });
    },
    [],
  );

  const getTriggerId = React.useCallback(
    (val: string) =>
      customIds[val]?.trigger ?? `${baseId}-trigger-${toIdPart(val)}`,
    [baseId, customIds],
  );
  const getContentId = React.useCallback(
    (val: string) =>
      customIds[val]?.content ?? `${baseId}-content-${toIdPart(val)}`,
    [baseId, customIds],
  );
  const getTriggerValue = React.useCallback((node: HTMLElement) => {
    for (const [val, el] of triggersRef.current) if (el === node) return val;
    return undefined;
  }, []);

  return (
    <TabsProvider
      value={{
        activeValue: (value ?? activeValue) as string,
        handleValueChange,
        registerTrigger,
        orientation,
        getTriggerId,
        getContentId,
        getTriggerValue,
        registerId,
      }}
    >
      <ReducedMotionConfig>
        <div data-slot="tabs" data-orientation={orientation} {...props}>
          {children}
        </div>
      </ReducedMotionConfig>
    </TabsProvider>
  );
}

function toIdPart(value: string) {
  return value.replace(/\s+/g, '-');
}

function isEnabled(tab: HTMLElement) {
  return (
    !tab.hasAttribute('disabled') &&
    tab.getAttribute('aria-disabled') !== 'true'
  );
}

