function toCrossfade<T>(target: T): T {
  if (!target || typeof target !== 'object' || Array.isArray(target)) {
    return target;
  }
  const { opacity } = target as { opacity?: unknown };
  return (opacity === undefined ? {} : { opacity }) as T;
}

const DEFAULT_INITIAL = { opacity: 0, scale: 0.8, filter: 'blur(10px)' };
const DEFAULT_ANIMATE = { opacity: 1, scale: 1, filter: 'blur(0px)' };
const DEFAULT_EXIT = { opacity: 0, scale: 0.8, filter: 'blur(10px)' };
const DEFAULT_TRANSITION: Transition = {
  type: 'spring',
  stiffness: 125,
  damping: 25,
  mass: 0.4,
};

type MorphingTextProps = Omit<HTMLMotionProps<'span'>, 'children'> & {
  delay?: number;
  loop?: boolean;
  holdDelay?: number;
  text: string | string[];
} & UseIsInViewOptions;

function MorphingText(props: MorphingTextProps) {
  return (
    <ReducedMotionConfig>
      <MorphingTextContent {...props} />
    </ReducedMotionConfig>
  );
}

function MorphingTextContent({
  ref,
  text,
  initial = DEFAULT_INITIAL,
  animate = DEFAULT_ANIMATE,
  exit = DEFAULT_EXIT,
  variants,
  transition: transitionProp,
  delay = 0,
  inView = false,
  inViewMargin = '0px',
  inViewOnce = true,
  loop = false,
  holdDelay = 2500,
  ...props
}: MorphingTextProps) {
  const { ref: localRef, isInView } = useIsInView(
    ref as React.Ref<HTMLElement>,
    {
      inView,
      inViewOnce,
      inViewMargin,
    },
  );

  const onScreen = useInView(localRef);
  const pageVisible = usePageVisible();
  const reduce = useShouldReduceMotion();

  const defaultTransition = useTempoTransition(DEFAULT_TRANSITION);
  const transition = transitionProp ?? defaultTransition;

  const uniqueId = React.useId();

  const texts = Array.isArray(text) ? text : [text];
  const count = texts.length;

  const [currentIndex, setCurrentIndex] = React.useState(0);
  const [started, setStarted] = React.useState(false);

  React.useEffect(() => {
    if (!isInView || started) return;
    const timeoutId = setTimeout(() => setStarted(true), delay);
    return () => clearTimeout(timeoutId);
  }, [isInView, started, delay]);

  const index = Math.min(currentIndex, count - 1);
  const finished = !loop && index >= count - 1;
  const playing = started && count > 1 && !finished && onScreen && pageVisible;

  React.useEffect(() => {
    if (!playing) return;
    const timeoutId = setTimeout(
      () => setCurrentIndex((prev) => (prev + 1) % count),
      holdDelay,
    );
    return () => clearTimeout(timeoutId);
  }, [playing, index, count, holdDelay]);

  const currentText = texts[index] ?? '';

  const chars = React.useMemo(() => {
    const counts = new Map<string, number>();
    return splitGraphemes(currentText).map((raw) => {
      const key = raw.normalize('NFC');
      const n = (counts.get(key) ?? 0) + 1;
      counts.set(key, n);
      return {
        layoutId: `${uniqueId}-${key}-${n}`,
        label: key === ' ' ? ' ' : key,
      };
    });
  }, [currentText, uniqueId]);

  return (
    <motion.span ref={localRef} data-slot="morphing-text" {...props}>
      <span className="sr-only" style={VISUALLY_HIDDEN}>
        {currentText}
      </span>
      <span aria-hidden="true">
        <AnimatePresence mode="popLayout" initial={false}>
          {chars.map((char) => (
            <motion.span
              key={char.layoutId}
              layoutId={char.layoutId}
              style={{ display: 'inline-block' }}
              initial={reduce ? toCrossfade(initial) : initial}
              animate={reduce ? toCrossfade(animate) : animate}
              exit={reduce ? toCrossfade(exit) : exit}
              variants={variants}
              transition={transition}
            >
              {char.label}
            </motion.span>
          ))}
        </AnimatePresence>
      </span>
    </motion.span>
  );
}

export { MorphingText, type MorphingTextProps };

'use client';

import * as React from 'react';
import { motion, type Transition } from 'motion/react';

import {
  useIsInView,
  type UseIsInViewOptions,
} from '../../../utils/use-is-in-view';
import {
  ReducedMotionConfig,
  transition as motionTransition,
  useMotionTokens,
  useShouldReduceMotion,
  useTempoTransition,
} from '../../../utils/motion';
import { VISUALLY_HIDDEN, splitGraphemes } from '../_text';

const formatCharacter = (char: string) => (char === ' ' ? ' ' : char);

const CHAR_STYLE: React.CSSProperties = {
  position: 'absolute',
  display: 'inline-block',
  backfaceVisibility: 'hidden',
};

const DEFAULT_TRANSITION: Transition = {
  duration: 0.5,
  delay: 0.1,
  ease: 'easeOut',
};

const BACK_OFFSET = 0.3;

type RollingTextProps = Omit<React.ComponentProps<'span'>, 'children'> & {
  text: string;
  transition?: Transition;
  delay?: number;
} & UseIsInViewOptions;

function RollingText(props: RollingTextProps) {
  return (
    <ReducedMotionConfig remount>
      <RollingTextContent {...props} />
    </ReducedMotionConfig>
  );
}

function RollingTextContent({
  ref,
  text,
  inView = false,
  inViewMargin = '0px',
  inViewOnce = true,
  transition: transitionProp,
  delay = 0,
  ...props
}: RollingTextProps) {
  const { ref: localRef, isInView } = useIsInView(
    ref as React.Ref<HTMLElement>,
    {
      inView,
      inViewOnce,
      inViewMargin,
    },
  );
  const reduce = useShouldReduceMotion();
  const { tempo } = useMotionTokens();
  const defaultTransition = useTempoTransition(DEFAULT_TRANSITION);
  const transition = transitionProp ?? defaultTransition;

  const rolled = isInView || reduce;

  const words = React.useMemo(
    () =>
      text
        .split(/(\s+)/)
        .filter(Boolean)
        .map((part) =>
          /^\s+$/.test(part)
            ? { space: true as const, part }
            : { space: false as const, chars: splitGraphemes(part) },
        ),
    [text],
  );
  const stepDelay = transition.delay ?? 0;

  let charIdx = 0;

  return (
    <span ref={localRef} data-slot="rolling-text" {...props}>
      <span aria-hidden="true">
        {words.map((word, wi) => {
          if (word.space) return <span key={`space-${wi}`}>{word.part}</span>;

          return (
            <span
              key={`word-${wi}`}
              style={{ display: 'inline-block', whiteSpace: 'nowrap' }}
            >
              {word.chars.map((char, ci) => {
                const charDelay = delay / 1000 + charIdx++ * stepDelay;
                const label = formatCharacter(char);

                return (
                  <span
                    key={`c-${wi}-${ci}`}
                    style={{
                      position: 'relative',
                      display: 'inline-block',
                      perspective: '9999999px',
                      transformStyle: 'preserve-3d',
                      width: 'auto',
                    }}
                  >
                    <motion.span
                      style={{ ...CHAR_STYLE, transformOrigin: '50% 25%' }}
                      initial={reduce ? false : { rotateX: 0 }}
                      animate={rolled ? { rotateX: 90 } : undefined}
                      transition={
                        reduce
                          ? motionTransition.instant
                          : { ...transition, delay: charDelay }
                      }
                    >
                      {label}
                    </motion.span>
                    <motion.span
                      style={{ ...CHAR_STYLE, transformOrigin: '50% 100%' }}
                      initial={reduce ? false : { rotateX: 90 }}
                      animate={rolled ? { rotateX: 0 } : undefined}
                      transition={
                        reduce
                          ? motionTransition.instant
                          : {
                              ...transition,
                              delay: charDelay + BACK_OFFSET * tempo,
                            }
                      }
                    >
                      {label}
                    </motion.span>
                    <span style={{ visibility: 'hidden' }}>{label}</span>
                  </span>
                );
              })}
            </span>
          );
        })}
      </span>

      <span className="sr-only" style={VISUALLY_HIDDEN}>
        {text}
      </span>
    </span>
  );
}

export { RollingText, type RollingTextProps };

'use client';

import * as React from 'react';
import {
  motion,
  AnimatePresence,
  useInView,
  type HTMLMotionProps,
  type Transition,
} from 'motion/react';

import {
  useIsInView,
  type UseIsInViewOptions,
} from '../../../utils/use-is-in-view';
import { usePageVisible } from '../../../utils/use-page-visible';
import { getStrictContext } from '../../../utils/strict-context';
import {
  ReducedMotionConfig,
  useShouldReduceMotion,
  useTempoTransition,
} from '../../../utils/motion';
import { VISUALLY_HIDDEN } from '../_text';

const DEFAULT_TRANSITION: Transition = { duration: 0.3, ease: 'easeOut' };

type RotatingTextContextType = {
  currentText: string;
  y: number;
  isInView: boolean;
  label: string;
};

const [RotatingTextProvider, useRotatingText] =
  getStrictContext<RotatingTextContextType>('RotatingTextContext');

type RotatingTextContainerProps = React.ComponentProps<'div'> & {
  text: string | string[];
  duration?: number;
  y?: number;
  delay?: number;
  align?: 'start' | 'center' | 'end';
} & UseIsInViewOptions;

function RotatingTextContainer({
  ref,
  text,
  y = -50,
  duration = 2000,
  delay = 0,
  style,
  inView = false,
  inViewMargin = '0px',
  inViewOnce = true,
  align,
  children,
  ...props
}: RotatingTextContainerProps) {
  const [index, setIndex] = React.useState(0);
  const [hasRotated, setHasRotated] = React.useState(false);

  const { ref: localRef, isInView } = useIsInView(
    ref as React.Ref<HTMLDivElement>,
    {
      inView,
      inViewOnce,
      inViewMargin,
    },
  );

  const onScreen = useInView(localRef);
  const pageVisible = usePageVisible();

  const texts = Array.isArray(text) ? text : [text];
  const count = texts.length;
  const playing = count > 1 && isInView && onScreen && pageVisible;

  React.useEffect(() => {
    if (!playing) return;
    const timeoutId = setTimeout(
      () => {
        setHasRotated(true);
        setIndex((prev) => (prev + 1) % count);
      },
      hasRotated ? duration : delay,
    );
    return () => clearTimeout(timeoutId);
  }, [playing, index, count, duration, delay, hasRotated]);

  const currentText = texts[index % count] ?? '';
  const label = texts.join(', ');

  const value = React.useMemo(
    () => ({ currentText, y, isInView, label }),
    [currentText, y, isInView, label],
  );

  return (
    <RotatingTextProvider value={value}>
      <div
        ref={localRef}
        data-slot="rotating-text-container"
        style={{
          overflow: 'hidden',
          paddingBlock: '0.25rem',
          ...style,
        }}
        {...props}
      >
        {align ? (
          <div
            data-slot="rotating-text-frame"
            style={{
              display: 'grid',
              justifyItems: align,
              alignItems: 'baseline',
            }}
          >
            {[...new Set(texts)].map((item) => (
              <span
                key={item}
                aria-hidden="true"
                style={{
                  gridArea: '1 / 1',
                  visibility: 'hidden',
                  whiteSpace: 'nowrap',
                }}
              >
                {item}
              </span>
            ))}
            <div
              style={{
                gridArea: '1 / 1',
                justifySelf: align,
                whiteSpace: 'nowrap',
              }}
            >
              {children}
            </div>
          </div>
        ) : (
          children
        )}
      </div>
    </RotatingTextProvider>
  );
}

type RotatingTextProps = Omit<HTMLMotionProps<'div'>, 'children'>;

function RotatingText(props: RotatingTextProps) {
  return (
    <ReducedMotionConfig>
      <RotatingTextContent {...props} />
    </ReducedMotionConfig>
  );
}

function RotatingTextContent({
  transition: transitionProp,
  ...props
}: RotatingTextProps) {
  const defaultTransition = useTempoTransition(DEFAULT_TRANSITION);
  const transition = transitionProp ?? defaultTransition;
  const { currentText, y, isInView, label } = useRotatingText();
  const reduce = useShouldReduceMotion();
  const travel = reduce ? 0 : y;

  return (
    <>
      <span className="sr-only" style={VISUALLY_HIDDEN}>
        {label}
      </span>
      <AnimatePresence mode="wait">
        {isInView && (
          <motion.div
            key={currentText}
            data-slot="rotating-text"
            aria-hidden="true"
            transition={transition}
            initial={{ opacity: 0, y: -travel }}
            animate={{ opacity: 1, y: 0 }}
            exit={{ opacity: 0, y: travel }}
            {...props}
          >
            {currentText}
          </motion.div>
        )}
      </AnimatePresence>
    </>
  );
}

export {
  RotatingTextContainer,
  RotatingText,
  useRotatingText,
  type RotatingTextContainerProps,
  type RotatingTextProps,
  type RotatingTextContextType,
};

'use client';

import * as React from 'react';
import {
  animate,
  motion,
  useMotionValue,
  useMotionValueEvent,
  useTransform,
  type HTMLMotionProps,
  type Transition,
} from 'motion/react';

import {
  useIsInView,
  type UseIsInViewOptions,
} from '../../../utils/use-is-in-view';
import { getStrictContext } from '../../../utils/strict-context';
import {
  ReducedMotionConfig,
  useShouldReduceMotion,
  useTempoTransition,
} from '../../../utils/motion';
import { VISUALLY_HIDDEN } from '../_text';

const formatter = new Intl.NumberFormat('en-US');

function generateRange(
  max: number,
  step: number,
  sideItemsCount: number,
): number[] {
  const result: number[] = [];
  const end = max + sideItemsCount * step;
  for (let value = end; value >= 0; value -= step) {
    result.push(value);
  }
  return result;
}

type ScrollingNumberDirection = 'ltr' | 'rtl' | 'ttb' | 'btt';

type ScrollingNumberContextType = {
  number: number;
  step: number;
  itemsSize: number;
  sideItemsCount: number;
  displayedItemsCount: number;
  isInView: boolean;
  direction: ScrollingNumberDirection;
  isVertical: boolean;
  range: number[];
  onNumberChange?: (value: number) => void;
};

const [ScrollingNumberProvider, useScrollingNumber] =
  getStrictContext<ScrollingNumberContextType>('ScrollingNumberContext');

type ScrollingNumberContainerProps = React.ComponentProps<'div'> & {
  number: number;
  step: number;
  itemsSize?: number;
  sideItemsCount?: number;
  direction?: ScrollingNumberDirection;
  onNumberChange?: (value: number) => void;
} & UseIsInViewOptions;

function ScrollingNumberContainer({
  ref,
  number,
  step: stepProp,
  itemsSize = 30,
  sideItemsCount = 2,
  direction = 'btt',
  inView = false,
  inViewMargin = '0px',
  inViewOnce = true,
  onNumberChange,
  style,
  children,
  ...props
}: ScrollingNumberContainerProps) {
  const step = stepProp > 0 ? stepProp : 1;
  const { ref: localRef, isInView } = useIsInView(
    ref as React.Ref<HTMLDivElement>,
    {
      inView,
      inViewOnce,
      inViewMargin,
    },
  );

  const displayedItemsCount = React.useMemo(
    () => 1 + sideItemsCount * 2,
    [sideItemsCount],
  );
  const isVertical = React.useMemo(
    () => direction === 'btt' || direction === 'ttb',
    [direction],
  );
  const range = React.useMemo(
    () => generateRange(number, step, sideItemsCount),
    [number, step, sideItemsCount],
  );

  return (
    <ScrollingNumberProvider
      value={{
        number,
        step,
        itemsSize,
        sideItemsCount,
        displayedItemsCount,
        isInView,
        direction,
        isVertical,
        range,
        onNumberChange,
      }}
    >
      <div
        ref={localRef}
        data-slot="scrolling-number-container"
        data-direction={direction}
        style={{
          position: 'relative',
          overflow: 'hidden',
          height: isVertical ? itemsSize * displayedItemsCount : undefined,
          width: !isVertical ? itemsSize * displayedItemsCount : undefined,
          ...style,
        }}
        {...props}
      >
        {children}
        <span className="sr-only" style={VISUALLY_HIDDEN}>
          {formatter.format(number)}
        </span>
      </div>
    </ScrollingNumberProvider>
  );
}

type ScrollingNumberHighlightProps = React.ComponentProps<'div'>;

function ScrollingNumberHighlight({
  style,
  ...props
}: ScrollingNumberHighlightProps) {
  const { itemsSize, isVertical, direction } = useScrollingNumber();
  return (
    <div
      data-slot="scrolling-number-highlight"
      data-direction={direction}
      style={{
        position: 'absolute',
        height: isVertical ? itemsSize : undefined,
        width: !isVertical ? itemsSize : undefined,
        left: !isVertical ? '50%' : undefined,
        top: isVertical ? '50%' : undefined,
        transform: !isVertical ? 'translateX(-50%)' : 'translateY(-50%)',
        zIndex: 0,
        ...style,
      }}
      {...props}
    />
  );
}

type ScrollingNumberProps = HTMLMotionProps<'div'> & {
  delay?: number;
  onCompleted?: () => void;
};

const DEFAULT_TRANSITION: Transition = { stiffness: 90, damping: 30 };

function resolveTransition(transition: Transition): Transition {
  if ('type' in transition || 'ease' in transition) return transition;
  return {
    type: 'spring',
    restDelta: 0.001,
    restSpeed: 0.01,
    ...transition,
  } as Transition;
}

const DIRECTION_FLEX: Record<
  ScrollingNumberDirection,
  React.CSSProperties['flexDirection']
> = {
  btt: 'column',
  ttb: 'column-reverse',
  rtl: 'row',
  ltr: 'row-reverse',
};

function ScrollingNumber(props: ScrollingNumberProps) {
  return (
    <ReducedMotionConfig remount>
      <ScrollingNumberContent {...props} />
    </ReducedMotionConfig>
  );
}

function ScrollingNumberContent({
  transition,
  delay = 0,
  onCompleted,
  style,
  ...props
}: ScrollingNumberProps) {
  const {
    itemsSize,
    sideItemsCount,
    displayedItemsCount,
    isInView,
    direction,
    isVertical,
    range,
    step,
    number,
    onNumberChange,
  } = useScrollingNumber();
  const reduce = useShouldReduceMotion();

  const sign = direction === 'ttb' || direction === 'ltr' ? -1 : 1;
  const initialPosition = -sign * itemsSize * sideItemsCount;
  const finalPosition = sign * itemsSize * (range.length - displayedItemsCount);

  const position = useMotionValue(initialPosition);
  const transform = useTransform(position, (p) =>
    isVertical ? `translateY(${p}px)` : `translateX(${p}px)`,
  );

  const defaultTransition = useTempoTransition(DEFAULT_TRANSITION);
  const transitionRef = React.useRef(transition ?? defaultTransition);
  React.useEffect(() => {
    transitionRef.current = transition ?? defaultTransition;
  });

  React.useEffect(() => {
    if (!isInView) return;

    if (reduce) {
      position.jump(finalPosition);
      return;
    }

    const timer = setTimeout(() => {
      animate(
        position,
        finalPosition,
        resolveTransition(transitionRef.current),
      );
    }, delay);
    return () => clearTimeout(timer);
  }, [isInView, finalPosition, position, delay, reduce]);

  React.useEffect(() => () => position.stop(), [position]);

  const indexAt = (p: number) => (sign * p) / itemsSize + sideItemsCount;
  const lastNumberRef = React.useRef<number | null>(null);
  const completedRef = React.useRef(false);

  React.useEffect(() => {
    completedRef.current = false;
  }, [number]);

  useMotionValueEvent(position, 'change', (p) => {
    const index = indexAt(p);
    const snapped = Math.min(Math.max(Math.round(index) * step, 0), number);
    if (snapped !== lastNumberRef.current) {
      lastNumberRef.current = snapped;
      onNumberChange?.(snapped);
    }

    const total = finalPosition - initialPosition;
    const progress = total === 0 ? 1 : (p - initialPosition) / total;
    if (!completedRef.current && progress >= 0.99) {
      completedRef.current = true;
      onCompleted?.();
    }
  });

  return (
    <motion.div
      aria-hidden="true"
      data-slot="scrolling-number"
      style={{
        position: 'absolute',
        top: direction === 'ttb' ? 0 : undefined,
        bottom: direction === 'btt' ? 0 : undefined,
        left: direction === 'ltr' ? 0 : undefined,
        right: direction === 'rtl' ? 0 : undefined,
        width: isVertical ? '100%' : undefined,
        height: !isVertical ? '100%' : undefined,
        display: 'flex',
        zIndex: 1,
        flexDirection: DIRECTION_FLEX[direction],
        transform,
        ...style,
      }}
      {...props}
    />
  );
}

type ScrollingNumberItemsProps = Omit<React.ComponentProps<'div'>, 'children'>;

function ScrollingNumberItems({ style, ...props }: ScrollingNumberItemsProps) {
  const { range, direction, itemsSize, isVertical } = useScrollingNumber();
  return range.map((value) => (
    <div
      key={value}
      data-slot="scrolling-number-item"
      data-value={value}
      data-direction={direction}
      style={{
        height: isVertical ? itemsSize : undefined,
        width: !isVertical ? itemsSize : undefined,
        ...style,
      }}
      {...props}
    >
      {formatter.format(value)}
    </div>
  ));
}

export {
  ScrollingNumberContainer,
  ScrollingNumber,
  ScrollingNumberHighlight,
  ScrollingNumberItems,
  useScrollingNumber,
  type ScrollingNumberContainerProps,
  type ScrollingNumberProps,
  type ScrollingNumberHighlightProps,
  type ScrollingNumberItemsProps,
  type ScrollingNumberDirection,
  type ScrollingNumberContextType,
};

'use client';

import * as React from 'react';
import { motion, useInView, type HTMLMotionProps } from 'motion/react';

import { usePageVisible } from '../../../utils/use-page-visible';
import {
  ReducedMotionConfig,
  scaleTransition,
  transition as motionTransition,
  useMotionTokens,
  useShouldReduceMotion,
} from '../../../utils/motion';
import { VISUALLY_HIDDEN, splitGraphemes } from '../_text';

const WAVE_REST = { x: 0, y: 0, scale: 1, rotateY: 0 };
const WAVE = {
  x: [0, 5, 0],
  y: [0, -5, 0],
  scale: [1, 1.1, 1],
  rotateY: [0, 15, 0],
};

type ShimmeringTextProps = Omit<HTMLMotionProps<'span'>, 'children'> & {
  text: string;
  duration?: number;
  wave?: boolean;
  color?: string;
  shimmeringColor?: string;
};

function ShimmeringText(props: ShimmeringTextProps) {
  return (
    <ReducedMotionConfig>
      <ShimmeringTextContent {...props} />
    </ReducedMotionConfig>
  );
}

function ShimmeringTextContent({
  ref,
  text,
  duration = 1,
  transition,
  wave = false,
  color = 'var(--color-neutral-500)',
  shimmeringColor = 'var(--color-neutral-300)',
  style,
  ...props
}: ShimmeringTextProps) {
  const localRef = React.useRef<HTMLSpanElement>(null);
  React.useImperativeHandle(ref, () => localRef.current as HTMLSpanElement);
  const { tempo } = useMotionTokens();

  const inView = useInView(localRef);
  const pageVisible = usePageVisible();
  const reduce = useShouldReduceMotion();
  const playing = inView && pageVisible && !reduce;

  const chars = React.useMemo(() => splitGraphemes(text ?? ''), [text]);

  return (
    <motion.span
      ref={localRef}
      data-slot="shimmering-text"
      style={
        {
          '--shimmering-color': shimmeringColor,
          '--color': color,
          color: 'var(--color)',
          position: 'relative',
          display: 'inline-block',
          perspective: '500px',
          ...style,
        } as React.CSSProperties
      }
      {...props}
    >
      <span className="sr-only" style={VISUALLY_HIDDEN}>
        {text}
      </span>
      <span
        aria-hidden
        style={{ display: 'inline-block', perspective: 'inherit' }}
      >
        {chars.map((char, i) => (
          <motion.span
            key={i}
            style={{
              display: 'inline-block',
              whiteSpace: 'pre',
              transformStyle: 'preserve-3d',
            }}
            initial={{
              ...(wave ? { scale: 1, rotateY: 0 } : {}),
              color: 'var(--color)',
            }}
            animate={
              playing
                ? {
                    ...(wave ? WAVE : {}),
                    color: [
                      'var(--color)',
                      'var(--shimmering-color)',
                      'var(--color)',
                    ],
                  }
                : {
                    ...(wave ? WAVE_REST : {}),
                    color: 'var(--color)',
                  }
            }
            transition={
              playing
                ? {
                    ...scaleTransition(
                      {
                        duration,
                        repeat: Infinity,
                        repeatType: 'loop',
                        repeatDelay: chars.length * 0.05,
                        delay: (i * duration) / chars.length,
                        ease: 'easeInOut',
                      },
                      tempo,
                    ),
                    ...transition,
                  }
                : motionTransition.instant
            }
          >
            {char}
          </motion.span>
        ))}
      </span>
    </motion.span>
  );
}

